/* A20 · frozen 80-lemma batch; 20-word audited checkpoints. */
(function (g) {
  'use strict';
  const D=g.RA.D;
  const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline — '+w+'; https://www.etymonline.com/word/'+w.toLowerCase()});
  const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
  const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
  const Q=(w,n,s,prompt,options,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'语境辨义',prompt,options,answer,explain});

  D('costly',{etymology:E('costly formed from cost, ultimately from Latin constare “stand at a price,” plus adjective-forming -ly; it can describe either a high price or serious consequences.','costly'),contexts:[C('costly.s2','公共安全','The delayed evacuation proved costly: two clinics lost power, several patients needed emergency transfers, and the town spent weeks repairing the damaged road.','延误疏散造成了严重代价：两家诊所断电，数名患者需要紧急转运，镇上还花了数周修复受损道路。','The delayed evacuation / proved costly / two clinics lost power / and the town spent weeks repairing the damaged road.','prove + adjective 表示结果证明具有某性质；冒号解释代价。','此处 costly 指损失和后果严重，并非物品售价昂贵。')],mistakes:[M('The inexpensive spare bolt was costly because it cost only two cents and caused no damage.','The inexpensive spare bolt was cheap; the delayed repair was costly because it caused extensive damage.','仅指低价物品且无不良后果不能称 costly；该词可指昂贵或造成重大代价。')],quiz:[Q('costly',1,1,'A costly repair requires $18,000. What does costly describe?',['a high price','a very quick repair','a repair offered for free'],'a high price','Here costly means expensive in money.'),Q('costly',2,2,'A costly mistake shuts down a factory for a month. What is emphasized?',['the serious loss or harm it causes','the small price of a tool','the mistake was easy to reverse'],'the serious loss or harm it causes','Costly can refer to painful consequences, not just a purchase price.'),Q('costly',3,1,'Which purchase is most clearly costly?',['a rare instrument priced at $40,000','a pencil sold for ten cents','a free library card'],'a rare instrument priced at $40,000','The unusually high price fits the monetary sense.'),Q('costly',4,2,'The phrase “a costly delay” most likely means a delay that?',['caused substantial losses','lasted exactly one minute','was paid for in coins'],'caused substantial losses','The adjective commonly describes expensive consequences.') ]});

  D('cosy',{etymology:E('cosy (US cozy) is recorded in Scots and northern English from the early modern period; its precise earlier origin is uncertain, so no deeper root is asserted.','cosy'),contexts:[C('cosy.s1','家居','On the rainy afternoon, Hana settled into a cosy chair beside the small stove, wrapped in a wool blanket with a book and a cup of tea.','那个下雨的下午，哈娜裹着羊毛毯，带着书和茶，坐进小炉子旁舒适的椅子里。','On the rainy afternoon / Hana settled into a cosy chair / beside the small stove / wrapped in a wool blanket with a book and a cup of tea.','settle into + 名词；cosy 描述温暖舒适的感觉，beside 引出位置。','炉火、毯子和安静环境营造温暖亲密的舒适感。')],mistakes:[M('The bare, freezing waiting room with metal benches and a broken heater felt cosy to every patient.','The warm, softly lit waiting room with padded chairs felt cosy to every patient.','冰冷、空荡且供暖损坏的房间缺少 cosy 所指的温馨舒适感。')],quiz:[Q('cosy',1,1,'Which room sounds cosiest on a cold evening?',['a small warm room with soft chairs and a fire','an unheated hall with hard metal benches','an open windy platform'],'a small warm room with soft chairs and a fire','Warmth and comfort are central to cosy.'),Q('cosy',2,1,'A cosy café is most likely?',['comfortable and welcoming','dangerously crowded with no warmth','a place for buying farm machinery'],'comfortable and welcoming','Cosy can describe an intimate, pleasant atmosphere.'),Q('cosy',3,1,'Choose the natural description of a blanket.',['a cosy wool blanket','a cosy measurement of 12 kilograms','a cosy verb that means to calculate'],'a cosy wool blanket','The adjective describes the comfort the blanket provides.'),Q('cosy',4,1,'The US spelling of cosy is usually?',['cozy','cossee','cossy'],'cozy','Cozy is the standard American spelling; cosy is common in British English.','spelling')]});

  D('cot',{etymology:E('cot came into English from Hindi khāṭ “bedstead,” via Anglo-Indian usage; the word later developed regional senses for a small bed.','cot'),contexts:[C('cot.s1','婴儿照护','Before the baby arrived, the parents checked that the cot had firm sides, a flat mattress, and no loose blankets that could cover the infant’s face.','宝宝出生前，父母检查婴儿床侧栏是否牢固、床垫是否平整，并确保没有可能盖住婴儿脸的松散毯子。','Before the baby arrived / the parents checked / that the cot had firm sides / and no loose blankets that could cover the infant’s face.','that 引导 checked 的宾语从句；英国英语中 cot 常指有高护栏的婴儿床。','安全侧栏与婴儿使用场景指向英式婴儿床义。')],mistakes:[M('She laid the newborn in an adult’s full-size double bed and called the narrow, high-sided cot a dining table.','She laid the newborn in the narrow, high-sided cot designed as a baby’s bed.','cot 可指婴儿床或简易床，不是餐桌；句中高护栏也明确是婴儿床。','word-choice')],quiz:[Q('cot',1,1,'In British English, a baby sleeps in a?',['cot','desk','saddle'],'cot','A cot is a small bed with high sides for a baby.'),Q('cot',2,1,'A camper unfolds a narrow cot in a tent. Here cot means?',['a portable camp bed','a baby’s pushchair','a cooking pot'],'a portable camp bed','Cot can also mean a simple portable bed, especially in US use.'),Q('cot',3,1,'Which safety feature is typical of a baby cot?',['high sides that help keep the infant in bed','a steering wheel','a row of dining plates'],'high sides that help keep the infant in bed','The British baby-bed sense is a small bed with protective sides.'),Q('cot',4,1,'Which sentence uses cot naturally?',['The nurse lowered the sleeping infant into the cot.','The carpenter poured soup into a cot.','The cot drove past the school.'],'The nurse lowered the sleeping infant into the cot.','The sentence uses cot as a baby’s bed.') ]});

  D('cottonwood',{etymology:E('cottonwood combines cotton and wood; the name alludes to the white cotton-like fluff surrounding the tree’s seeds, not to cotton fibers being harvested from its trunk.','cottonwood'),contexts:[C('cottonwood.s1','植物观察','In early summer, cottonwood seeds drifted across the river path in white tufts, while the tall poplars that had released them stood along the bank.','初夏，棉白杨的种子裹着白色绒毛飘过河边小路，而释放种子的高大杨树就立在岸旁。','In early summer / cottonwood seeds drifted across the river path in white tufts / while the tall poplars / that had released them / stood along the bank.','cottonwood 是树名；while 对照种子飘落与母树的位置。','白色棉絮状种子来自河边的杨树，说明 cottonwood 的命名特征。')],mistakes:[M('The botanist identified the cottonwood by harvesting cotton fibers from its wooden trunk.','The botanist identified the cottonwood by its poplar leaves and cottony seed fluff.','cottonwood 是杨属树木，名字来自种子绒毛，不会从树干产棉纤维。','meaning')],quiz:[Q('cottonwood',1,1,'A cottonwood is a kind of?',['poplar tree','cotton-producing shrub','pine cone'],'poplar tree','Cottonwood is a poplar that releases fluffy seed coverings.'),Q('cottonwood',2,1,'Why is this tree called cottonwood?',['its seeds are wrapped in white cotton-like fluff','its trunk is woven into cotton cloth','it grows only in cotton fields'],'its seeds are wrapped in white cotton-like fluff','The name refers to the fluffy material around the seeds.'),Q('cottonwood',3,1,'A riverside tree releases drifting white tufts in summer. What is it likely to be?',['a cottonwood','a cactus','an oak producing acorns'],'a cottonwood','Cottonwood seed fluff commonly drifts when released.'),Q('cottonwood',4,1,'Which claim about cottonwood is accurate?',['It belongs to the poplar group.','It is a domesticated cotton plant.','It is an animal that lives in rivers.'],'It belongs to the poplar group.','The noun names a poplar tree, not a cotton crop.') ]});

  D('cougar',{etymology:E('cougar came into English from French cougar, probably through a Brazilian Indigenous language such as Tupi; ultimate derivation is uncertain. The animal is also called a puma or mountain lion.','cougar'),contexts:[C('cougar.s1','野生动物','A motion camera photographed a cougar crossing the ridge after dark; wildlife officers warned hikers to keep children close and never approach the large solitary cat.','夜间运动相机拍到一只美洲狮越过山脊；野生动物管理人员提醒徒步者照看好孩子，绝不要靠近这种大型独居猫科动物。','A motion camera photographed a cougar crossing the ridge after dark / wildlife officers warned hikers / to keep children close / and never approach the large solitary cat.','photograph + 宾语 + 现在分词；warn sb to do 表示发出安全警告。','大型独居猫科动物及其野外活动情境符合美洲狮义。')],mistakes:[M('The zoo described its cougar as a small domesticated house cat that eats only seeds.','The zoo described its cougar as a large wild cat related to the puma and mountain lion.','cougar 指大型野生猫科动物，不是食种子的家猫。')],quiz:[Q('cougar',1,1,'A cougar is also known as a?',['puma or mountain lion','river otter','domestic tabby'],'puma or mountain lion','Cougar, puma, and mountain lion name the same large cat.'),Q('cougar',2,1,'A hiker sees a large solitary cat on a western ridge. The animal may be a?',['cougar','cattle dog','beaver'],'cougar','Cougars are solitary wild cats found across the Americas.'),Q('cougar',3,1,'Which precaution makes sense in cougar country?',['keep a safe distance from the wild cat','feed it from a picnic table','try to touch its cubs'],'keep a safe distance from the wild cat','A cougar is a potentially dangerous large wild predator.'),Q('cougar',4,1,'The word cougar refers to?',['a mammal in the cat family','a fluffy seed of a poplar','a type of courtroom'],'a mammal in the cat family','The dictionary sense is the large cat, also called a puma.') ]});

  D('councillor',{etymology:E('councillor is council plus the agent/person suffix -or; council entered English through Anglo-French from Latin concilium “assembly, meeting.” The double-l spelling is standard in British usage.','councillor'),contexts:[C('councillor.s1','地方政府','Residents asked their councillor to oppose the plan to close the neighbourhood library, and she brought their signed petition to the next city council meeting.','居民请地方议会议员反对关闭社区图书馆的计划，她把居民签名的请愿书带到了下一次市议会会议。','Residents asked their councillor / to oppose the plan to close the neighbourhood library / and she brought their signed petition / to the next city council meeting.','ask + 人 + to do；councillor 是当选地方议会成员。','居民向代表所在选区的地方议员请愿，符合职位义。')],mistakes:[M('The town councillor was appointed as the national ambassador by a foreign king and had no role in local government.','The town councillor was elected to represent residents on the local council.','councillor 的职务是地方议会成员，不是外交使节。','word-choice')],quiz:[Q('councillor',1,1,'Residents elect a councillor to serve on a?',['local council','ship’s engine','hospital operating team'],'local council','A councillor is an elected member of a town, city, or county council.'),Q('councillor',2,1,'Who should a resident contact about a neighbourhood council decision?',['their local councillor','a mountain guide','a court witness with no public role'],'their local councillor','Councillors represent local residents in local government.'),Q('councillor',3,1,'In British spelling, which form names an elected local representative?',['councillor','counselor only','counsellor only'],'councillor','Councillor with double l and -or is the political office; counselor/counsellor advises.' ,'confusable'),Q('councillor',4,1,'A councillor speaks at a town meeting about parks. This person is acting as?',['a local elected official','a private therapist','a delivery driver'],'a local elected official','The role is membership in local government.') ]});

  D('counseling',{etymology:E('counseling is counsel (from Anglo-French conseil, Latin consilium “advice, deliberation”) plus -ing; the US spelling has one l, while British counselling commonly has two.','counseling'),contexts:[C('counseling.s1','学校心理支持','After the student began avoiding class, the school arranged counseling with a trained professional who helped him talk through anxiety and plan manageable steps back into lessons.','学生开始逃避上课后，学校安排他接受专业咨询，帮助他谈论焦虑，并制定逐步回归课堂的可行计划。','After the student began avoiding class / the school arranged counseling with a trained professional / who helped him talk through anxiety / and plan manageable steps back into lessons.','arrange counseling with a professional；关系从句说明咨询提供者如何帮助学生。','受训人员提供持续的个人问题支持，符合心理咨询义。')],mistakes:[M('After reporting panic attacks, the student received counseling from an untrained stranger who offered no guidance or support.','After reporting panic attacks, the student received counseling from a trained professional who offered guidance and support.','counseling 指受训人员给予的建议和支持；完全没有指导支持不符该义。')],quiz:[Q('counseling',1,1,'A student meets regularly with a trained therapist to discuss anxiety. This is?',['counseling','a court hearing','a parcel delivery'],'counseling','Counseling provides advice and support about personal problems.'),Q('counseling',2,2,'A small business hires counseling on tax rules from an expert. Here counseling means?',['specialist advice service','treatment for a broken arm','a group of elected officials'],'specialist advice service','The noun can refer to a service that gives expert advice.'),Q('counseling',3,1,'Which spelling is standard in American English?',['counseling','counselling only','counceling'],'counseling','American English generally uses one l in counseling.' ,'spelling'),Q('counseling',4,1,'A counselor helps someone examine a personal problem and consider next steps. The activity is?',['counseling','council voting','courier work'],'counseling','The activity means advice and support from a trained person.') ]});

  D('counsellor',{etymology:E('counsellor combines counsel, from Anglo-French conseil and Latin consilium “advice,” with the agent suffix -or; the doubled l spelling is usual in British English.','counsellor'),contexts:[C('counsellor.s1','学校支持','The school counsellor met with Jae privately, listened to his concerns about bullying, and helped him identify an adult he could safely approach if it happened again.','学校辅导员私下与杰会面，倾听他对霸凌的担忧，并帮他确定若事件重演时可以安全求助的成年人。','The school counsellor met with Jae privately / listened to his concerns about bullying / and helped him identify an adult / he could safely approach if it happened again.','listen to concerns；help + 宾语 + 动词原形；counsellor 指提供建议和支持的专业人员。','校方人员倾听个人困难并给出求助建议，符合辅导员义。')],mistakes:[M('The counsellor delivered parcels along a route and never advised or supported anyone.','The courier delivered parcels along a route; the counsellor advised and supported students.','送包裹的职业是 courier；counsellor 是提供指导支持的人。','confusable')],quiz:[Q('counsellor',1,1,'A school counsellor is trained to?',['advise and support students','deliver packages across town','preside over a criminal trial'],'advise and support students','A counsellor helps with personal, educational, or similar problems.'),Q('counsellor',2,1,'Which spelling is commonly used in British English for an adviser?',['counsellor','councilor only','counsillor'],'counsellor','British English commonly doubles the l in counsellor.' ,'spelling'),Q('counsellor',3,1,'A person helps a teenager plan how to respond to stress. That person may be a?',['counsellor','courthouse','cottonwood'],'counsellor','The profession involves giving personal advice and support.'),Q('counsellor',4,1,'Which job is different from a counsellor?',['a courier carrying express parcels','a trained school adviser','a therapist who listens to personal concerns'],'a courier carrying express parcels','A courier carries things; a counsellor gives advice.') ]});

  D('counselor',{etymology:E('counselor is formed from counsel (Anglo-French conseil, ultimately Latin consilium “advice”) plus -or; US spelling uses one l and the noun also has a legal-adviser sense.','counselor'),contexts:[C('counselor.s2','美国法律','Before signing the settlement, the company’s counselor reviewed the liability clause and explained which obligations would remain enforceable after the dispute ended.','签署和解协议之前，公司的法律顾问审阅了责任条款，并解释争议结束后哪些义务仍可执行。','Before signing the settlement / the company’s counselor reviewed the liability clause / and explained / which obligations would remain enforceable / after the dispute ended.','法律语境中的 counselor 指提供法律意见的律师；before + 动名词短语交代时间。','审阅法律条款并解释责任，是法律顾问义 s2。')],mistakes:[M('The corporation’s counselor delivered legal advice in the contract but was described as a mail carrier paid only to transport letters.','The corporation’s counselor reviewed the contract and advised the company on its legal obligations.','提供法律意见的律师是法律顾问，不是负责运输信件的 courier。','confusable')],quiz:[Q('counselor',1,2,'In a US contract dispute, a company’s counselor is most likely?',['a lawyer advising the company','a bus driver','a local elected council member'],'a lawyer advising the company','In American usage, counselor can mean a lawyer who gives legal advice.'),Q('counselor',2,1,'A trained person helps an employee discuss stress at work. That person may be a?',['counselor','courier','council chamber'],'counselor','Counselor also names an adviser or support professional.'),Q('counselor',3,2,'Which action best fits legal counselor?',['reviewing a contract and explaining legal risks','delivering a parcel to a courthouse','painting a courtroom wall'],'reviewing a contract and explaining legal risks','A legal counselor advises on law and obligations.'),Q('counselor',4,1,'US counselor differs from councillor because counselor generally means?',['an adviser or lawyer','an elected local-government member','a mountain cat'],'an adviser or lawyer','A councillor is elected to a local council; counselor provides counsel.','confusable')]});

  D('counterargument',{etymology:E('counterargument combines counter- “opposed” with argument, from Old French argument and Latin argumentum “evidence, proof”; it is a reasoned case against a claim.','counterargument'),contexts:[C('counterargument.s1','辩论写作','The essay acknowledges that remote work reduces commuting, then presents a counterargument: new employees may learn more slowly without informal help from colleagues.','文章承认远程办公减少通勤，接着提出一项反方论点：如果缺少同事的非正式帮助，新员工的学习速度可能变慢。','The essay acknowledges that remote work reduces commuting / then presents a counterargument / new employees may learn more slowly / without informal help from colleagues.','present a counterargument；冒号后的内容具体说明反对理由。','论点针对前面的支持主张，给出相反理由，符合反论义。')],mistakes:[M('Her counterargument supported the proposal by repeating its benefits and offered no reason against it.','Her counterargument challenged the proposal by explaining a likely cost it had overlooked.','counterargument 是反对某论点的理由；单纯重复支持理由不构成反论。')],quiz:[Q('counterargument',1,1,'A counterargument is a reason used to?',['oppose a claim','repeat a claim without comment','name the claim’s author'],'oppose a claim','Counterargument means an argument presented against another position.'),Q('counterargument',2,1,'A debate team supports a rail project; its opponent says the cost estimate ignores repairs. That objection is a?',['counterargument','conclusion supporting the same claim','weather forecast'],'counterargument','The repair-cost objection offers a reason against the proposal.'),Q('counterargument',3,1,'Which belongs in a paragraph introducing a counterargument?',['“Critics object that the plan would displace local residents.”','“Everyone who agrees with me is correct.”','“The plan is called Project North.”'],'“Critics object that the plan would displace local residents.”','It fairly states an opposing reason.'),Q('counterargument',4,1,'A writer includes a counterargument mainly to?',['address a plausible opposing reason','hide all evidence for the thesis','replace reasoning with a title'],'address a plausible opposing reason','A counterargument makes the opposing case explicit for discussion.') ]});

  D('countercurrent',{etymology:E('countercurrent joins counter- “opposite” and current, from Latin currere “to run”; it names a flow moving against the main direction.','countercurrent'),contexts:[C('countercurrent.s1','海洋学','A cold countercurrent moved north beneath the warm surface stream, carrying nutrient-rich water toward the coast against the dominant southbound flow.','一股寒冷的逆流在温暖的表层水流下向北移动，把富含营养物质的海水带向海岸，方向与主要的南流相反。','A cold countercurrent moved north beneath the warm surface stream / carrying nutrient-rich water toward the coast / against the dominant southbound flow.','beneath 引出下方位置；against the dominant flow 明示水流方向相反。','两股水流相向，符合 countercurrent 的物理流动义。')],mistakes:[M('A countercurrent is the main river flow moving in exactly the same direction as every nearby stream.','A countercurrent is a flow moving opposite to the principal current.','同向的主流不是 countercurrent；counter- 标明与主方向相反。','word-formation')],quiz:[Q('countercurrent',1,1,'A countercurrent flows?',['opposite to the principal current','in exactly the same direction as the main flow','only in a circle with no movement'],'opposite to the principal current','The prefix counter- signals opposition in direction.'),Q('countercurrent',2,1,'A lab sends two fluids through neighboring tubes in opposite directions. The opposing flow is a?',['countercurrent','counterargument','counterexample'],'countercurrent','The word names a flow moving opposite to the main current.'),Q('countercurrent',3,1,'In a river report, a countercurrent would be?',['a smaller flow running against the dominant stream','the riverbank vegetation','a measurement of rainfall'],'a smaller flow running against the dominant stream','Its defining feature is opposite direction.'),Q('countercurrent',4,1,'Choose the best paraphrase: “a countercurrent developed below the surface.”',['an opposing flow formed beneath the surface','a current stopped and became dry land','an argument was written under a letter'],'an opposing flow formed beneath the surface','Countercurrent refers to an opposing flow, here below the surface.') ]});

  D('counterexample',{etymology:E('counterexample is counter- “opposing” plus example, from Old French essample and Latin exemplum; a single instance can disprove a universal rule.','counterexample'),contexts:[C('counterexample.s1','数学推理','The claim that every prime number is odd has a simple counterexample: 2 is prime, yet it is even.','“每个素数都是奇数”这一说法有一个简单反例：2 是素数，但它是偶数。','The claim / that every prime number is odd / has a simple counterexample / 2 is prime / yet it is even.','冒号给出 counterexample；yet 对照“是素数”与“是偶数”。','2 是满足前提却否定全称规则的具体实例，构成反例。')],mistakes:[M('A counterexample proves that a universal rule has no exceptions by repeating an instance that follows the rule.','A counterexample disproves a universal rule by giving an instance that violates it.','反例必须违反被检验的全称规律，而不是举一个符合规律的例子。')],quiz:[Q('counterexample',1,1,'To disprove “all birds can fly,” which is a counterexample?',['a penguin','a sparrow in flight','an eagle with wings'],'a penguin','One flightless bird is an instance that contradicts the universal claim.'),Q('counterexample',2,1,'A counterexample is a particular case that?',['shows a rule or hypothesis is false','repeats the rule in different words','proves every possible case without testing one'],'shows a rule or hypothesis is false','A counterexample supplies a case against a general claim.'),Q('counterexample',3,1,'A student claims all rectangles are squares. Which object is a counterexample?',['a rectangle 2 cm by 5 cm','a 4 cm by 4 cm square','a triangle'],'a rectangle 2 cm by 5 cm','It is a rectangle but not a square, so it refutes “all.”'),Q('counterexample',4,1,'Why is the number 2 a counterexample to “all primes are odd”?',['It is prime but not odd.','It is odd but not prime.','It is neither a number nor a prime.'],'It is prime but not odd.','The example satisfies the category while violating the claimed property.') ]});

  D('countermeasure',{etymology:E('countermeasure is counter- “opposing” plus measure in the sense of an action or step; the compound names a response intended to prevent or reduce an unwanted effect.','countermeasure'),contexts:[C('countermeasure.s2','网络安全','After a rival group began flooding the service with requests, the security team deployed a countermeasure that blocked suspicious traffic while allowing verified customers through.','竞争团体开始用请求淹没服务后，安全团队部署了反制措施，拦截可疑流量，同时让已验证客户正常访问。','After a rival group began flooding the service with requests / the security team deployed a countermeasure / that blocked suspicious traffic / while allowing verified customers through.','deploy a countermeasure；that 从句说明该反制措施的功能。','措施针对敌方或有害行动并直接予以阻止，符合反制手段义 s2。')],mistakes:[M('The security team called unrestricted access for the attacking traffic a countermeasure against the attack.','The security team blocked the attacking traffic as a countermeasure against the attack.','放任攻击流量通过不会反制或减轻攻击，不能称 countermeasure。')],quiz:[Q('countermeasure',1,1,'A countermeasure is intended to?',['stop or reduce a harmful effect','increase the damage being addressed','record an event without responding'],'stop or reduce a harmful effect','A countermeasure is a step taken to lessen a problem.'),Q('countermeasure',2,2,'A radar jammer deployed to oppose an enemy missile is a?',['countermeasure','counterexample','countercurrent'],'countermeasure','The step actively opposes an adversary’s action.'),Q('countermeasure',3,1,'A factory installs a filter to reduce toxic emissions. The filter is a?',['countermeasure','counterargument','courier'],'countermeasure','It is an action intended to reduce a harmful effect.'),Q('countermeasure',4,2,'Which best fits the adversarial sense of countermeasure?',['a defense designed to defeat an opponent’s tactic','a textbook example that supports a theorem','a flow moving opposite a river'],'a defense designed to defeat an opponent’s tactic','The second sense is a step taken specifically to oppose an enemy action.') ]});

  D('counterproductive',{etymology:E('counterproductive combines counter- “against” with productive; counter- ultimately reflects Latin contra “against.” The adjective describes an action that works against its intended result.','counterproductive'),contexts:[C('counterproductive.s1','团队管理','To improve concentration, the manager banned every short break; workers became more distracted and made more errors, so the rule proved counterproductive.','为了提高专注度，经理禁止所有短暂休息；员工反而更分心、错误更多，因此这条规定适得其反。','To improve concentration / the manager banned every short break / workers became more distracted and made more errors / so the rule proved counterproductive.','prove + adjective；so 引出实际后果与预期目标相反。','禁休息的规则损害了它原本想提高的专注度，符合适得其反义。')],mistakes:[M('A counterproductive measure reliably achieves its stated aim and improves the outcome exactly as intended.','An effective measure achieves its stated aim; a counterproductive measure works against it.','完全实现目标的是有效措施；counterproductive 指阻碍原本目标。')],quiz:[Q('counterproductive',1,1,'A strict rule causes the very problem it was meant to prevent. The rule is?',['counterproductive','highly productive','unrelated to the outcome'],'counterproductive','It produces an effect opposite to the intended result.'),Q('counterproductive',2,1,'Which action may be counterproductive when trying to reduce stress?',['adding unnecessary late-night meetings','allowing realistic deadlines','providing quiet breaks'],'adding unnecessary late-night meetings','The added meetings are likely to worsen the stress one wants to reduce.'),Q('counterproductive',3,1,'The prefix counter- in counterproductive suggests?',['working against','working twice as fast','working in a courtroom'],'working against','Counter- contributes the sense of opposition.'),Q('counterproductive',4,1,'A teacher’s public shaming makes a shy student participate even less. The approach is?',['counterproductive','a successful confidence-building measure','a form of countercurrent'],'counterproductive','The approach undermines its apparent goal of encouraging participation.') ]});

  D('courier',{etymology:E('courier came through French courrier from Italian corriere, a messenger, related to correre “to run”; a courier carries urgent messages or parcels.','courier'),contexts:[C('courier.s1','快递服务','The courier collected the signed contract at noon and delivered it to the client’s office before the bank closed, obtaining a receipt at the front desk.','快递员中午取走签好的合同，并在银行下班前送到客户办公室，在前台取得了收据。','The courier collected the signed contract at noon / and delivered it to the client’s office / before the bank closed / obtaining a receipt at the front desk.','collect and deliver 描述 courier 运送文件的工作；before 从句表示截止时间。','负责快速送递合同并取得签收记录，符合信使/快递员义。')],mistakes:[M('The courier provided long-term psychotherapy to patients but never carried messages or parcels.','The counselor provided psychotherapy; the courier carried the signed documents to the client.','提供心理治疗的是 counselor；courier 的工作是递送信件和包裹。','confusable')],quiz:[Q('courier',1,1,'A courier is hired to?',['carry letters or parcels quickly','repair a courthouse roof','advise a city council'],'carry letters or parcels quickly','A courier transports messages and packages.'),Q('courier',2,2,'On a guided holiday, a courier employed to accompany visitors is?',['a tour guide or trip assistant','a wild mountain cat','a legal counterargument'],'a tour guide or trip assistant','Courier can also name an employee who guides tourists on a trip.'),Q('courier',3,1,'Which task most clearly belongs to a courier?',['delivering a passport to a hotel by 3 p.m.','deciding a criminal verdict','milking cows in a cowshed'],'delivering a passport to a hotel by 3 p.m.','The core delivery sense is carrying important items to a destination.'),Q('courier',4,1,'The office sent the original deed by courier. This means it used?',['a rapid delivery service','a therapy session','a town election'],'a rapid delivery service','Courier can refer to the person or company providing fast delivery.') ]});

  D('courteously',{etymology:E('courteously is courteous plus -ly; courteous came through Anglo-French corteis from Old French cortois, “of a court,” describing polished manners.','courteously'),contexts:[C('courteously.s1','公共服务','When the passenger explained that the ramp was blocked, the station attendant listened courteously, apologized for the delay, and called a colleague to clear it.','乘客说明坡道被挡住时，车站工作人员有礼貌地倾听，为延误道歉，并叫同事来清理通道。','When the passenger explained / the station attendant listened courteously / apologized for the delay / and called a colleague to clear it.','courteously 修饰 listened，说明以尊重他人的方式倾听。','认真倾听、道歉并提供协助，表现出礼貌和尊重。')],mistakes:[M('He courteously interrupted the speaker, shouted an insult, and refused to let her finish.','He courteously waited for the speaker to finish and then responded respectfully.','辱骂、打断并拒绝倾听是无礼行为，与 courteously 的礼貌含义相反。')],quiz:[Q('courteously',1,1,'To answer courteously is to answer?',['politely and respectfully','angrily and with an insult','without hearing the question'],'politely and respectfully','Courteously means in a polite, respectful manner.'),Q('courteously',2,1,'Which receptionist behaves courteously?',['She listens, greets the visitor, and explains the delay calmly.','She mocks the visitor and slams the door.','She ignores everyone and turns off the lights.'],'She listens, greets the visitor, and explains the delay calmly.','Calm, respectful treatment illustrates courteously.'),Q('courteously',3,1,'In “he courteously declined,” the adverb describes?',['the polite manner of declining','the price of the item','the number of people present'],'the polite manner of declining','-ly makes an adverb modifying how he declined.'),Q('courteously',4,1,'Choose the natural use.',['The clerk courteously explained the return policy.','The clerk courteously weighed 40 kilograms.','The courteously was painted blue.'],'The clerk courteously explained the return policy.','The adverb describes a respectful way of speaking or acting.') ]});

  D('courthouse',{etymology:E('courthouse is court plus house. Court came through Old French cort from Latin cohors/cortis, an enclosed yard and later a tribunal; house names the building that contains it.','courthouse'),contexts:[C('courthouse.s1','司法程序','Witnesses entered the courthouse through a security checkpoint and followed signs to the courtroom where the civil trial was scheduled to begin at ten.','证人通过安检进入法院，按指示牌前往预定十点开庭的审判室。','Witnesses entered the courthouse through a security checkpoint / and followed signs to the courtroom / where the civil trial was scheduled to begin at ten.','courthouse 指设有法庭的公共建筑；where 引导地点定语从句，说明审判室的位置。','安检入口和审判室表明该建筑是法院。')],mistakes:[M('The courthouse was a private bedroom where the family stored its luggage and held no public hearings.','The courthouse was the public building where judges heard the case.','私人卧室不是举行法庭审理的公共建筑。')],quiz:[Q('courthouse',1,1,'A courthouse is a public building that houses?',['courts and courtrooms','a cotton crop','a river current'],'courts and courtrooms','The building contains places where legal hearings and trials are held.'),Q('courthouse',2,1,'A person summoned as a witness should look for the?',['courthouse','cowshed','countercurrent'],'courthouse','Legal proceedings take place in a courthouse.'),Q('courthouse',3,1,'In the US, a courthouse may also contain?',['county government offices','a mountain-lion habitat','a poplar grove only'],'county government offices','Many US courthouses also house county offices.'),Q('courthouse',4,1,'The jury walked from the courthouse lobby into the courtroom. What is the difference?',['the courthouse is the whole building; a courtroom is the room for the trial','they are both names for a delivery driver','a courtroom is a courthouse outside the law'],'the courthouse is the whole building; a courtroom is the room for the trial','The courtroom is one room inside the larger courthouse.') ]});

  D('courtly',{etymology:E('courtly comes from court plus -ly, originally describing the refined behaviour expected at a royal or noble court; court ultimately passed through Old French from Latin cohors.','courtly'),contexts:[C('courtly.s1','历史小说','Though the visitors arrived without warning, the ambassador greeted each one with courtly composure, offering a formal bow and carefully measured words.','尽管访客不期而至，大使仍以宫廷般的从容逐一问候，正式鞠躬，说话谨慎得体。','Though the visitors arrived without warning / the ambassador greeted each one with courtly composure / offering a formal bow / and carefully measured words.','with courtly composure 描述正式典雅的礼仪；offering 分词说明问候方式。','正式鞠躬、措辞审慎体现旧式宫廷礼节般的优雅谦恭。')],mistakes:[M('The courtly host screamed insults, shoved every guest aside, and refused all greetings.','The courtly host greeted each guest with a formal bow and respectful words.','侮辱和推搡客人体现粗鲁，而 courtly 表示优雅、谦恭、正式。')],quiz:[Q('courtly',1,1,'Courtly manners are?',['elegant, formal, and very polite','carelessly rude','limited to repairing roads'],'elegant, formal, and very polite','Courtly describes the refined politeness associated with a royal court.'),Q('courtly',2,1,'A courtly bow would most likely be made?',['with deliberate formal grace','while shouting an insult','to measure a river current'],'with deliberate formal grace','Courtly often suggests ceremonious, polished manners.'),Q('courtly',3,1,'Which scene feels courtly?',['a noble addresses guests with elegant courtesy','a mechanic curses at customers','a courier drops parcels in the street'],'a noble addresses guests with elegant courtesy','The scene displays the formal elegance associated with courtly behaviour.'),Q('courtly',4,1,'A “courtly compliment” is likely?',['polished and ceremoniously polite','a blunt threat','a calculation of court fees'],'polished and ceremoniously polite','The adjective carries a refined and formal tone.') ]});

  D('courtroom',{etymology:E('courtroom combines court, from Old French cort and Latin cohors/cortis, with room; it names the room in which a legal trial or hearing is held.','courtroom'),contexts:[C('courtroom.s1','庭审现场','The judge asked everyone in the courtroom to remain silent while the witness identified the signature on the original contract.','法官要求法庭里所有人保持安静，同时让证人在原始合同上辨认签名。','The judge asked everyone in the courtroom to remain silent / while the witness identified the signature / on the original contract.','ask + 人 + to do；in the courtroom 表示庭审活动发生的房间。','法官、证人及证据辨认的场景明确是审判室。')],mistakes:[M('The trial took place in the courthouse parking lot, which the report inaccurately called the courtroom.','The trial took place in the courtroom, the room inside the courthouse where hearings are held.','停车场不是进行审判或听证的房间；courtroom 与 courthouse 不能混用。','confusable')],quiz:[Q('courtroom',1,1,'A courtroom is the room where?',['a trial or hearing is held','a baby sleeps','a cow is milked'],'a trial or hearing is held','Courtroom names the room used for legal proceedings.'),Q('courtroom',2,1,'The witness entered the courtroom to?',['give evidence before the judge','deliver lunch to a farm','plant cottonwood seeds'],'give evidence before the judge','Witness testimony is given in a courtroom.'),Q('courtroom',3,1,'Which sentence uses courtroom accurately?',['Silence fell over the courtroom as the jury returned.','The courtroom carried the parcel across town.','They milked three cows in the courtroom shed.'],'Silence fell over the courtroom as the jury returned.','The courtroom is where the jury and trial proceedings are present.'),Q('courtroom',4,1,'A courtroom is usually part of a larger?',['courthouse','counterexample','coastline'],'courthouse','A courthouse is the building; the courtroom is a room within it.') ]});

  D('courtship',{etymology:E('courtship is court plus -ship, denoting a state or process; court as a verb once meant to pay attention to someone or seek favour, and the compound came to mean wooing before marriage.','courtship'),contexts:[C('courtship.s1','恋爱关系','Their courtship lasted nearly two years: they visited one another’s families, discussed where to live, and decided to marry only after learning how they handled disagreements.','他们的恋爱期持续了近两年：双方拜访彼此家人，讨论居住地点，并在了解彼此如何处理分歧后才决定结婚。','Their courtship lasted nearly two years / they visited one another’s families / discussed where to live / and decided to marry only after learning how they handled disagreements.','courtship 可表示婚前恋爱求偶阶段；冒号列出期间的交往活动。','婚前双方相互了解并考虑结婚，符合恋爱期义 s1。')],mistakes:[M('Their courtship began after their wedding and ended before they met, so the word described their married life.','Their courtship began when they started trying to win each other before deciding to marry.','courtship 指婚前求爱和相互了解的阶段，不是婚后生活。')],quiz:[Q('courtship',1,1,'Courtship usually describes the period when two people?',['try to win each other before marriage','serve together on a jury','transport parcels for work'],'try to win each other before marriage','The common sense is a romantic period preceding marriage.'),Q('courtship',2,2,'A company’s courtship of a major investor means it is?',['trying hard to gain the investor’s support','planning the investor’s wedding','opposing the investor with a countermeasure'],'trying hard to gain the investor’s support','Courtship can metaphorically mean efforts to win support or business.'),Q('courtship',3,1,'Which event belongs to a couple’s courtship?',['meeting each other’s families while considering marriage','celebrating their tenth wedding anniversary only','filing a lawsuit against a neighbour'],'meeting each other’s families while considering marriage','This occurs during the period of trying to win one another before marriage.'),Q('courtship',4,1,'In a business article, “the firm’s courtship of new customers” means?',['its determined effort to attract them','its formal marriage to them','its refusal to sell anything'],'its determined effort to attract them','The figurative sense is an effort to win a customer or supporter.') ]});


  D('cove',{etymology:E('Cove came from Old English cofa, “chamber or recess”; its coastal sense developed for a sheltered hollow in a shoreline.','cove'),contexts:[C('cove.s1','海岸地貌','The fishing boat slipped through a narrow opening into the cove, where high cliffs sheltered the still water from the strongest waves outside.','渔船穿过狭窄入口驶入小海湾，高耸的悬崖使平静的海水免受外侧强浪冲击。','The fishing boat slipped through a narrow opening into the cove / where high cliffs sheltered the still water / from the strongest waves outside.','where 从句修饰 cove；shelter A from B 表示保护 A 免受 B。','狭窄入口和悬崖遮蔽表明这是小而隐蔽的海湾。')],mistakes:[M('The ship entered a broad, open ocean with no sheltered inlet, which the map labelled a cove.','The ship entered a small sheltered inlet, which the map labelled a cove.','开阔无蔽的大洋不是小海湾或凹地。')],quiz:[Q('cove',1,1,'A cove is a?',['small sheltered bay','large open desert','room for a jury'],'small sheltered bay','A cove is a small bay, often with a narrow entrance.'),Q('cove',2,1,'A boat finds calm water in a small inlet behind cliffs. It has reached a?',['cove','countercurrent','cottonwood'],'cove','The sheltered hollow along a coast fits the geographical sense.'),Q('cove',3,2,'In “the carpenter coved the ceiling edge,” cove is used as?',['a verb meaning to hollow or arch inward','a noun for a messenger','an adjective meaning expensive'],'a verb meaning to hollow or arch inward','Cove can be a verb for making a surface concave.'),Q('cove',4,1,'Which description best fits a cove?',['a small inlet partly enclosed by land','a continent-wide plain','a courtroom'],'a small inlet partly enclosed by land','A cove is a small recessed bay or hollow.') ]});

  D('coverage',{etymology:E('Coverage is cover plus the noun-forming suffix -age; cover came through Old French covrir from Latin cooperire “cover completely.” Its scope depends on context.','coverage'),contexts:[C('coverage.s2','新闻报道','The station’s live coverage of the flood included interviews with residents, hourly updates from the river gauge, and a map showing which roads were closed.','电视台对洪水的实时报道包括居民访谈、河流水位计的每小时更新，以及显示封路情况的地图。','The station’s live coverage of the flood / included interviews with residents / hourly updates from the river gauge / and a map showing which roads were closed.','coverage of an event 指新闻报道；including 的并列名词说明报道内容。','访谈、实时更新和地图构成事件的新闻报道内容，符合 s2。')],mistakes:[M('The news coverage of the flood consisted only of insurance benefits and did not report the event.','The news coverage of the flood reported conditions, interviews, and road closures.','没有报道事件内容的保险赔付额不是新闻报道义 coverage。')],quiz:[Q('coverage',1,2,'A channel sends reporters to give live coverage of an election. What is coverage?',['news reporting about the event','the area a Wi-Fi signal reaches','an insurance limit'],'news reporting about the event','Coverage has a news-reporting sense.'),Q('coverage',2,1,'A router’s coverage reaches every room in the house. This means?',['the area reached by its signal','the reporter’s account of a debate','the amount an insurer will pay'],'the area reached by its signal','The word can mean the extent or area covered.'),Q('coverage',3,3,'A policy lists medical coverage of $500,000. This refers to?',['the amount protected by insurance','the length of a news broadcast','the surface area of a roof'],'the amount protected by insurance','Insurance coverage is the amount or risk protected.'),Q('coverage',4,2,'Which phrase means reports about a court case?',['news coverage of the trial','the trial’s insurance coverage','the router’s coverage'],'news coverage of the trial','News coverage is reporting about an event.') ]});

  D('covert',{etymology:E('Covert came through Anglo-French and Old French covert, “covered or hidden,” the past participle of covrir, ultimately from Latin cooperire. As an adjective it means secret; as a noun it can mean sheltering brush.','covert'),contexts:[C('covert.s1','调查行动','The agency conducted a covert review of the contractor’s records, keeping the inquiry secret until investigators had secured the original files.','该机构秘密审查了承包商的记录，在调查人员取得原始文件前一直未公开调查。','The agency conducted a covert review of the contractor’s records / keeping the inquiry secret / until investigators had secured the original files.','covert 修饰 review；keeping 分词短语说明保密方式。','调查没有公开承认，且刻意保密，符合隐蔽秘密义 s1。')],mistakes:[M('The agency announced its covert operation on television in advance and invited the targets to watch.','The agency kept its covert operation secret from the targets.','公开宣布并邀请目标观看，与 covert 所指秘密、不公开的行动相反。')],quiz:[Q('covert',1,1,'A covert operation is conducted?',['secretly','in full public view','only under water'],'secretly','Covert describes an action kept hidden or unacknowledged.'),Q('covert',2,2,'A fox hides in a dense covert. Here covert means?',['a thicket providing shelter','a public courtroom','an argument against a rule'],'a thicket providing shelter','Covert can be a noun for brush where game animals hide.'),Q('covert',3,1,'Which activity is most clearly covert?',['secretly recording a meeting without alerting the target','publishing the complete plan before it starts','holding an open press conference'],'secretly recording a meeting without alerting the target','Secrecy is central to the adjective.'),Q('covert',4,1,'Choose the natural phrase.',['covert surveillance','covert sunshine measured in litres','a covert that means a courier'],'covert surveillance','Covert naturally modifies a secret activity.') ]});

  D('covetous',{etymology:E('Covetous comes from covet plus -ous; covet entered English through Old French coveitier, from Latin cupiditas “desire.” The adjective describes eager desire, especially for what another has.','covetous'),contexts:[C('covetous.s1','人物性格','Although the neighbour admired the old house, she was not covetous: she congratulated its owners and never tried to take what belonged to them.','尽管邻居很欣赏那栋老房子，她并不觊觎它：她祝贺房主，从未企图夺走他人的财物。','Although the neighbour admired the old house / she was not covetous / she congratulated its owners / and never tried to take what belonged to them.','covetous 表示贪图他人所有物；although 引出转折对照。','句子通过“不试图占有他人房屋”凸显觊觎义的反面。')],mistakes:[M('He was covetous of his colleague’s promotion, so he felt entirely content when the colleague received it and never wished for the position.','He was covetous of his colleague’s promotion and strongly wished he had received it himself.','满足于别人获得机会且无占有欲，不能称 covetous。')],quiz:[Q('covetous',1,1,'A covetous person strongly wants?',['something another person has','nothing at all, even basic needs','to give every possession away'],'something another person has','Covetous describes an eager, often envious desire to possess.'),Q('covetous',2,2,'Someone covetous of wealth beyond what is fair is?',['greedily eager to possess it','indifferent to it','legally appointed to collect taxes'],'greedily eager to possess it','The second sense emphasizes excessive desire for wealth or status.'),Q('covetous',3,1,'Which behaviour seems covetous?',['envying a neighbour’s house and scheming to obtain it','admiring a painting but respecting its owner','returning a lost wallet'],'envying a neighbour’s house and scheming to obtain it','The person intensely wants what belongs to another.'),Q('covetous',4,1,'Choose the correct phrase.',['a covetous look at another family’s land','a covetous temperature of 20 degrees','covetous the envelope to the clerk'],'a covetous look at another family’s land','Covetous is an adjective describing desire or attitude.') ]});

  D('cowardice',{etymology:E('Cowardice is coward plus -ice, a noun-forming suffix. Coward came through Old French coart, probably from an older term associated with a hare’s short tail; the historical derivation is not fully certain.','cowardice'),contexts:[C('cowardice.s1','责任与勇气','The captain called it cowardice to abandon the injured crew without warning, because the officers had time to send help but chose to protect only themselves.','船长称不发出警告就抛下受伤船员是怯懦，因为军官有时间求援，却选择只顾自己。','The captain called it cowardice / to abandon the injured crew without warning / because the officers had time to send help / but chose to protect only themselves.','call + object + noun complement；because 从句说明逃避责任的原因。','在有能力履责时因害怕而弃同伴，符合怯懦、逃避危险或责任义。')],mistakes:[M('The firefighter’s careful retreat after an explicit evacuation order was automatically cowardice, even though the area had become unsafe.','The firefighter’s refusal to help anyone solely to avoid personal risk could be called cowardice.','按命令撤离危险区并非必然怯懦；需有逃避危险或责任的可辩护情境。')],quiz:[Q('cowardice',1,1,'Cowardice is behaviour showing?',['fearful refusal to face danger or duty','careful courage under pressure','a high price'],'fearful refusal to face danger or duty','Cowardice means shameful fear and avoidance of responsibility or danger.'),Q('cowardice',2,1,'Which action most clearly shows cowardice?',['a guard deserts an injured colleague solely to avoid any risk','a guard follows an evacuation order during a gas leak','a guard requests backup before entering a dangerous area'],'a guard deserts an injured colleague solely to avoid any risk','Abandoning a duty only to escape personal danger fits the meaning.'),Q('cowardice',3,1,'The abstract noun cowardice names?',['a kind of fearful conduct','a person’s official certificate','the act of growing cotton'],'a kind of fearful conduct','The suffix -ice forms the quality or conduct noun.'),Q('cowardice',4,1,'A report condemns cowardice among officials who?',['refused to protect others despite having a safe way to help','carefully planned a rescue','admitted uncertainty and asked for assistance'],'refused to protect others despite having a safe way to help','Avoiding a duty through shameful fear is cowardice.') ]});

  D('cower',{etymology:E('Cower is recorded in Middle English as couren, “to crouch or huddle”; its earlier origin is uncertain, so no unsupported root is assigned.','cower'),contexts:[C('cower.s1','受惊反应','When thunder cracked directly overhead, the frightened dog cowered beneath the bench, lowering its body and trembling until the storm moved away.','雷声在头顶炸响时，受惊的狗畏缩到长椅下面，压低身体发抖，直到风暴移远。','When thunder cracked directly overhead / the frightened dog cowered beneath the bench / lowering its body and trembling / until the storm moved away.','cower 不及物；lowering 与 trembling 描写身体动作。','压低身体躲避突发巨响，符合因恐惧或疼痛而畏缩的义。')],mistakes:[M('At the loud crash, the fearless dog cowered proudly on top of the table with its body raised and no sign of fear.','At the loud crash, the frightened dog cowered beneath the table, shrinking away from the sound.','昂首迎向声音且毫无畏惧并非 cower；该动词描写因害怕而蜷缩退避。')],quiz:[Q('cower',1,1,'A person who cowers usually?',['crouches or shrinks back in fear','stands tall to greet an audience','runs a debate club'],'crouches or shrinks back in fear','Cower describes lowering the body and moving back from fear or pain.'),Q('cower',2,2,'After the manager threatens him, the employee cowers rather than confronting her. Here cower means?',['avoids facing someone because he feels weak','bows ceremonially to a monarch','crosses a room repeatedly'],'avoids facing someone because he feels weak','The figurative sense is to retreat from someone out of weakness or fear.'),Q('cower',3,1,'Which reaction best illustrates cower?',['a child curls up under a desk during an explosion','a child raises a hand to ask a question','a child strides confidently onto the stage'],'a child curls up under a desk during an explosion','Curling down and back from danger is the physical sense.'),Q('cower',4,1,'Choose the natural sentence.',['The cat cowered when the fireworks burst.','The cat cowered the bowl with milk.','The cower delivered a parcel.'],'The cat cowered when the fireworks burst.','Cower is an intransitive verb describing a fearful posture.') ]});

  D('cowhand',{etymology:E('Cowhand combines cow and hand, where hand has long meant a worker or hired helper; the compound is an American term for a person who herds and tends cattle.','cowhand'),contexts:[C('cowhand.s1','牧场工作','At dawn the cowhand rode out to check the water troughs, count the calves, and move the herd away from a damaged section of fence.','黎明时牧牛工骑马出去检查水槽、清点小牛，并把牛群从受损的围栏处赶开。','At dawn / the cowhand rode out / to check the water troughs / count the calves / and move the herd away from a damaged section of fence.','cowhand 是牧场工人；三个并列不定式列出照料牛群的任务。','骑马巡查饮水、牛犊和围栏，是牧牛工照看牛群的工作。')],mistakes:[M('The cowhand spent the shift managing court appeals in a city courthouse and never worked with cattle.','The cowhand spent the shift herding cattle and checking the ranch fences.','处理法庭上诉是法律工作人员职责；cowhand 指牧牛工。','word-choice')],quiz:[Q('cowhand',1,1,'A cowhand works mainly with?',['cattle on a ranch','courtroom transcripts','cottonwood seeds'],'cattle on a ranch','A cowhand is a worker who herds and tends cattle.'),Q('cowhand',2,1,'Which task most likely belongs to a cowhand?',['moving a herd to fresh pasture','writing a counterargument in court','advising a client on a contract'],'moving a herd to fresh pasture','Herd management is characteristic ranch work.'),Q('cowhand',3,1,'The word hand in cowhand means?',['worker or hired helper','the animal’s hoof','a unit of court coverage'],'worker or hired helper','Hand can denote a worker in occupational compounds.'),Q('cowhand',4,1,'A ranch hired a cowhand for the summer. It hired?',['someone to look after its cattle','a counselor for school pupils','a courier for city parcels'],'someone to look after its cattle','Cowhand names an agricultural worker caring for cattle.') ]});

  D('cowshed',{etymology:E('Cowshed combines cow and shed, the latter meaning a simple roofed building; it is a farm structure where cattle are sheltered and, in one use, milked.','cowshed'),contexts:[C('cowshed.s1','农场设施','Before the freezing night, the farmer brought the young cattle into the cowshed, spread clean straw on the floor, and checked that the ventilation remained open.','寒冷夜晚来临前，农场主把小牛赶进牛棚，在地上铺好干净稻草，并检查通风口仍然敞开。','Before the freezing night / the farmer brought the young cattle into the cowshed / spread clean straw on the floor / and checked the ventilation.','bring cattle into a building；并列动词说明牛棚的 shelter 用途。','牛只进入建筑物过夜并铺设垫草，符合牲畜住棚义。')],mistakes:[M('The cowshed was an open swimming pool where no cattle could shelter from rain or cold.','The cowshed was a farm building where the cattle could shelter from rain and cold.','露天游泳池不是安置或保护奶牛的农舍建筑。')],quiz:[Q('cowshed',1,1,'A cowshed is a farm building for?',['housing cows','holding a jury trial','delivering parcels'],'housing cows','The usual sense is a shed in which cows are housed.'),Q('cowshed',2,2,'On some farms, workers use the cowshed as a place for?',['milking or sheltering cattle','storing courtroom evidence only','growing cotton fibers'],'milking or sheltering cattle','The second listed sense includes a shed used for milking.'),Q('cowshed',3,1,'Where would a farmer spread fresh straw for cattle at night?',['in a cowshed','in a courthouse','in a cove'],'in a cowshed','A cowshed provides shelter for cattle.'),Q('cowshed',4,1,'What does shed contribute to the compound cowshed?',['a simple roofed building','a trained adviser','an opposing current'],'a simple roofed building','The compound names a shed used for cows.') ]});

  D('coyote',{etymology:E('Coyote entered English from Mexican Spanish coyote, from Nahuatl coyotl; the Nahuatl animal name is the source, with no further root claimed here.','coyote'),contexts:[C('coyote.s1','北美野生动物','The rancher found coyote tracks around the chicken enclosure at dawn and reinforced the lower fence rather than trying to approach the wary wild animal.','黎明时牧场主在鸡舍周围发现郊狼脚印，于是加固下层围栏，而没有试图接近这种警惕的野生动物。','The rancher found coyote tracks around the chicken enclosure at dawn / and reinforced the lower fence / rather than trying to approach the wary wild animal.','coyote 是北美野生犬科动物；rather than 对照防护措施和直接接近。','脚印出现在鸡舍附近，并被视为野生动物，符合郊狼义。')],mistakes:[M('The field guide called the coyote a domesticated cow that grazes in a cowshed.','The field guide called the coyote a wild canid native to parts of North America.','coyote 是野生犬科动物，不是家牛。','confusable')],quiz:[Q('coyote',1,1,'A coyote is a wild animal in the?',['dog family','poplar family','crustacean group'],'dog family','It is a slender wild canid native to western and central North America.'),Q('coyote',2,1,'Tracks near a western ranch might belong to a?',['coyote','courier','councillor'],'coyote','Coyotes are wild canids that live in many ranching regions.'),Q('coyote',3,1,'Which description fits a coyote?',['a wild canid, not a domestic cow','a kind of courtroom','a cotton-like seed fluff'],'a wild canid, not a domestic cow','The animal belongs to the canid family.'),Q('coyote',4,1,'A coyote should be treated as?',['a wild animal observed at a safe distance','a farm worker who tends cows','a baby bed'],'a wild animal observed at a safe distance','Coyotes are wild predators, not domesticated livestock.') ]});

  D('crabgrass',{etymology:E('Crabgrass combines crab and grass; crab here reflects the grass’s low, spreading, crab-like growth habit, not a claim that it is eaten by crabs.','crabgrass'),contexts:[C('crabgrass.s1','草坪养护','By midsummer, crabgrass had spread from the dry edge of the lawn in low, creeping clumps that crowded out the finer turf grass.','盛夏时，马唐从草坪干燥边缘以低矮匍匐的草丛蔓延开来，挤掉了更细密的草坪草。','By midsummer / crabgrass had spread from the dry edge of the lawn / in low, creeping clumps / that crowded out the finer turf grass.','spread from A；that 定语从句说明草丛挤占草坪的效果。','低矮匍匐并侵占草坪的杂草是 crabgrass 的典型特征。')],mistakes:[M('The gardener planted crabgrass as a tall shade tree with a woody trunk and branches.','The gardener removed crabgrass, a low creeping weed that spreads through the lawn.','crabgrass 是草本杂草，不是有树干和树枝的乔木。','word-choice')],quiz:[Q('crabgrass',1,1,'Crabgrass is best described as?',['a spreading weed grass','a poplar tree','a freshwater lobster'],'a spreading weed grass','It is a tough weed that creeps through and crowds turf.'),Q('crabgrass',2,1,'A lawn is being invaded by a low grass that forms creeping clumps. The weed may be?',['crabgrass','cottonwood','crayfish'],'crabgrass','Low, spreading growth is typical of crabgrass.'),Q('crabgrass',3,1,'Why do lawn owners often dislike crabgrass?',['it crowds out desired turf','it produces poplar wood','it carries parcels'],'it crowds out desired turf','Crabgrass is a weed that competes with and crowds out lawn grasses.'),Q('crabgrass',4,1,'The word names a type of?',['grass weed','small courtroom','city councillor'],'grass weed','Crabgrass is a grass, specifically a troublesome weed.') ]});

  D('craftsman',{etymology:E('Craftsman joins craft, from Old English cræft “skill or strength,” and man; it traditionally means a skilled maker and is now commonly used without implying that the worker is male.','craftsman'),contexts:[C('craftsman.s1','木工制作','The craftsman fitted each hand-carved stair rail to the old staircase, checking the joints twice so the finished pieces matched the building’s original detail.','这位工匠把每根手工雕刻的扶手安装到老楼梯上，反复检查接合处，使成品与建筑原有细节相符。','The craftsman fitted each hand-carved stair rail / to the old staircase / checking the joints twice / so the finished pieces matched the building’s original detail.','craftsman 指熟练制作物品的工人；checking 分词说明其精细工艺。','手工雕刻并精准装配展现了熟练的手工技艺。')],mistakes:[M('The craftsman made the cabinet by guessing randomly, ignored every joint, and had no skill in the work.','The craftsman made the cabinet with trained skill, fitting each joint carefully.','完全无技能且随意制作与 craftsman 所指熟练工匠相矛盾。')],quiz:[Q('craftsman',1,1,'A craftsman is a skilled person who often?',['makes things carefully by hand','judges a court trial','carries urgent parcels'],'makes things carefully by hand','The central sense is a skilled maker.'),Q('craftsman',2,2,'A job posting seeks a craftsman trained to repair antique furniture. It seeks?',['a worker with a skilled manual trade','an elected local official','a wildlife biologist only'],'a worker with a skilled manual trade','The word also describes someone whose job requires trained manual skill.'),Q('craftsman',3,1,'Which worker best fits craftsman?',['a potter who shapes and finishes each vessel by hand','a buyer who only pays an invoice','a person who never makes or repairs anything'],'a potter who shapes and finishes each vessel by hand','The maker’s careful skill fits the noun.'),Q('craftsman',4,1,'The passage praises a craftsman’s workmanship. It praises?',['the skill and care of the making','the speed of a river current','the size of an insurance policy'],'the skill and care of the making','Workmanship highlights the skilled quality of a craftsman’s work.') ]});

  D('craftspeople',{etymology:E('Craftspeople is the gender-inclusive plural of craftsperson, built from craft (“skill, trade”) and person; it is used as a plural noun for skilled makers.','craftspeople'),contexts:[C('craftspeople.s1','手工艺集市','At the spring market, craftspeople demonstrated basket weaving, pottery, and woodcarving, then explained how each material affected the strength and finish of the objects.','春季集市上，工匠们现场展示编篮、制陶和木雕，随后解释不同材料如何影响成品的坚固度和表面效果。','At the spring market / craftspeople demonstrated basket weaving, pottery, and woodcarving / then explained how each material affected the strength and finish of the objects.','craftspeople 是复数主语，故用 demonstrated；多项手工艺列举其工作。','多名熟练制作者展示手工技艺，符合 craftspeople 的复数义。')],mistakes:[M('The craftspeople was a single machine that shaped clay without any human makers.','The craftspeople were skilled people who shaped and finished the pottery by hand.','craftspeople 是复数人称名词，不能与 was 配合，更不是机器。','grammar')],quiz:[Q('craftspeople',1,1,'Craftspeople are?',['skilled workers who practise a craft','a single legal document','wild animals in a herd'],'skilled workers who practise a craft','Craftspeople is the plural term for people skilled in a craft.'),Q('craftspeople',2,1,'Choose the grammatically correct sentence.',['The craftspeople were displaying their pottery.','The craftspeople was displaying a single bowl.','A craftspeople makes one object.'],'The craftspeople were displaying their pottery.','The noun is plural, so the plural verb were is appropriate.','grammar'),Q('craftspeople',3,1,'A ceramics fair features many potters and weavers. They are?',['craftspeople','a courthouse','a counterexample'],'craftspeople','The plural covers people who make things through skilled crafts.'),Q('craftspeople',4,1,'The word craftspeople is often preferred when referring to?',['makers of any gender','only male makers','only machines'],'makers of any gender','Craftspeople is an inclusive plural noun for skilled makers.') ]});

  D('craftworker',{etymology:E('Craftworker combines craft (“a skilled trade or making skill”) and worker; it straightforwardly names someone employed in a craft.','craftworker'),contexts:[C('craftworker.s1','传统制造','The craftworker shaped the leather by hand, stitched the seams with waxed thread, and inspected every buckle before the finished bags went to the shop.','这位手艺人手工塑形皮革，用蜡线缝合接缝，并在成品包送往商店前检查每个扣件。','The craftworker shaped the leather by hand / stitched the seams with waxed thread / and inspected every buckle / before the finished bags went to the shop.','craftworker 作主语，三个并列谓语展示其手工生产工作。','制作皮革制品并检查细节，符合从事手工技艺者的职业义。')],mistakes:[M('The craftworker had no craft, did not work, and produced nothing but was hired to make traditional goods.','The craftworker used a trained craft skill to make and finish the traditional goods.','没有手艺也没有制作行为，与“从事手工艺工作的工人”不相符。')],quiz:[Q('craftworker',1,1,'A craftworker is someone employed in?',['making objects through a craft','delivering legal verdicts','herding wild coyotes'],'making objects through a craft','The compound means a worker who practises a craft.'),Q('craftworker',2,1,'Which person best fits craftworker?',['a glassblower paid to make decorative bowls','a tourist buying a bowl','a judge reading a verdict'],'a glassblower paid to make decorative bowls','Glassblowing is a skilled craft used to make objects.'),Q('craftworker',3,1,'The compound’s first part, craft, points to?',['a skilled trade or making skill','an insurance payment','a narrow coastal bay'],'a skilled trade or making skill','Craft refers to skill or a skilled trade.'),Q('craftworker',4,1,'A museum hires a craftworker to restore handwoven cloth. The worker will likely?',['use specialized manual skill','conduct a criminal trial','guide a tourist bus'],'use specialized manual skill','The job involves skilled work in a craft.') ]});

  D('crafty',{etymology:E('Crafty is craft plus adjective-forming -y. The word developed senses of skill and cleverness, often with a negative suggestion of trickery; context decides which applies.','crafty'),contexts:[C('crafty.s1','谈判策略','The crafty negotiator asked each supplier for a separate estimate, then used the differences to secure a lower price without revealing the company’s budget.','这位狡黠的谈判者分别向每家供应商索取报价，再利用报价差异压低价格，同时不透露公司的预算。','The crafty negotiator asked each supplier for a separate estimate / then used the differences / to secure a lower price / without revealing the company’s budget.','crafty 修饰 negotiator；then 引出借助策略达成目标的动作。','策略性地隐藏预算并利用信息差，体现带有诡计意味的机敏 s1。')],mistakes:[M('The crafty scheme was completely open, straightforward, and made no attempt to gain an advantage by trickery.','The clever but crafty scheme hid its purpose and sought an advantage through trickery.','坦率公开且没有诡计的做法缺少 crafty 的狡黠含义。')],quiz:[Q('crafty',1,1,'A crafty plan often gets what its maker wants by?',['using clever tricks','following every step openly with no strategy','making a pottery bowl by hand only'],'using clever tricks','The common adjective sense is clever in a sly or tricky way.'),Q('crafty',2,2,'A crafty woodworker is praised for?',['skill in making things','dishonest dealings','being a courtroom'],'skill in making things','Crafty can also mean skilful at making things.'),Q('crafty',3,1,'Which character seems crafty?',['a fox who creates a believable distraction to escape','a person who states every plan plainly','a worker who simply follows a printed list'],'a fox who creates a believable distraction to escape','The character uses a trick to get the desired result.'),Q('crafty',4,1,'In “a crafty reply,” the word most likely suggests?',['a shrewd, possibly deceptive answer','a technical manual skill only','an answer about a coastal bay'],'a shrewd, possibly deceptive answer','In ordinary description, crafty often carries a sly or devious tone.') ]});

  D('cramming',{etymology:E('Cramming is the -ing form of cram, from Old English crammian “press in, stuff”; it can mean hurried intensive study or forcing things into limited space.','cramming'),contexts:[C('cramming.s1','备考学习','After postponing revision all term, Eli spent the night cramming for the biology exam, memorizing diagrams and definitions until he could barely stay awake.','整学期拖着没复习后，伊莱熬夜突击准备生物考试，背图表和定义，直到几乎撑不住。','After postponing revision all term / Eli spent the night cramming for the biology exam / memorizing diagrams and definitions / until he could barely stay awake.','spend time cramming for an exam；memorizing 说明集中突击复习内容。','复习被压缩到考前一夜，符合临时集中学习义 s1。')],mistakes:[M('She began reviewing one chapter every week months before the exam and called the steady schedule cramming.','She tried to learn the whole course in one night just before the exam, cramming.','分散、提前安排的长期复习不属于短时间填鸭式突击。')],quiz:[Q('cramming',1,1,'A student who is cramming usually studies?',['intensively in a short period before a test','a few pages each month for years','without any exam or material'],'intensively in a short period before a test','Cramming is study packed into a brief time, often just before an exam.'),Q('cramming',2,1,'Which action is physical cramming?',['forcing too many books into a small suitcase','studying vocabulary the night before a test','taking a planned rest day'],'forcing too many books into a small suitcase','Cram can also mean forcing things into limited space.'),Q('cramming',3,1,'“Cramming all the facts into one paragraph” means?',['packing too much into a small space','forgetting every fact deliberately','spreading facts across several volumes'],'packing too much into a small space','The verb sense involves pressing many things together.'),Q('cramming',4,1,'Which schedule most clearly involves cramming?',['studying twelve chapters overnight before an exam','reviewing one chapter weekly throughout a term','taking the exam after completing the course gradually'],'studying twelve chapters overnight before an exam','Last-minute concentrated study is cramming.') ]});

  D('cramped',{etymology:E('Cramped is the past participle and adjective from cramp, a word related to Old French crampe “spasm or clamp”; cramped describes space so restricted that movement is difficult.','cramped'),contexts:[C('cramped.s1','狭小居住空间','Six interns shared one cramped office, where their desks nearly touched and opening a filing drawer blocked the narrow path to the only window.','六名实习生共用一间狭窄的办公室，桌子几乎挨在一起，打开文件柜抽屉就会挡住通往唯一窗户的窄道。','Six interns shared one cramped office / where their desks nearly touched / and opening a filing drawer blocked the narrow path / to the only window.','cramped 修饰 office；where 从句具体解释空间为何难以活动。','家具拥挤到阻挡通道，符合狭窄局促、行动不便义。')],mistakes:[M('The spacious hall was cramped, with empty floor space for hundreds of people to move freely in every direction.','The tiny hall was cramped, with little room for people to move between the packed chairs.','可自由容纳许多人活动的宽敞空间不是 cramped。')],quiz:[Q('cramped',1,1,'A cramped room is?',['so small or crowded that movement is difficult','large, empty, and easy to cross','quiet but outdoors'],'so small or crowded that movement is difficult','Cramped describes a space that restricts movement.'),Q('cramped',2,1,'Which train compartment feels cramped?',['one with passengers and bags blocking nearly every seat and aisle','one with wide empty aisles and few passengers','one that is outdoors beside the track'],'one with passengers and bags blocking nearly every seat and aisle','Crowding and restricted movement fit cramped.'),Q('cramped',3,1,'The word cramped can describe?',['a workspace with no room to move','a building with huge open halls','a river current moving upstream'],'a workspace with no room to move','The adjective refers to confined, crowded space.'),Q('cramped',4,1,'Choose the natural sentence.',['We worked in a cramped kitchen barely large enough for two people.','The cramped plain stretched for miles with no obstruction.','She cramped courteously to the visitor.'],'We worked in a cramped kitchen barely large enough for two people.','The kitchen is restricted in space.') ]});

  D('crank',{etymology:E('Crank is recorded in Middle English for a bent or winding shape and later for a bent arm used to turn a shaft; the verb means to turn or operate such a handle.','crank'),contexts:[C('crank.s2','机械维修','With the starter battery dead, the mechanic cranked the old engine by hand, turning the handle steadily until the fuel caught and the motor began to run.','启动电池没电后，修理工用手摇动老发动机曲柄，持续转动，直到燃料点着、发动机开始运转。','With the starter battery dead / the mechanic cranked the old engine by hand / turning the handle steadily / until the fuel caught and the motor began to run.','crank 作动词表示摇曲柄启动机器；until 从句说明操作结果。','通过转动曲柄使发动机启动，符合动词义 s2。')],mistakes:[M('The mechanic cranked the engine by leaving its handle untouched and refusing to turn it.','The mechanic cranked the engine by turning its handle until it started.','不转动曲柄不能称为 cranking；该动作依靠旋转手柄运作机器。')],quiz:[Q('crank',1,1,'A hand crank is?',['an angled arm or handle used to turn a shaft','a legal adviser','a sheltered coastal bay'],'an angled arm or handle used to turn a shaft','The noun names a handle that turns a mechanism.'),Q('crank',2,2,'To crank an old engine is to?',['turn its handle to start or operate it','write an opposing essay','shelter it from rain'],'turn its handle to start or operate it','The verb means operating or starting by turning a crank.'),Q('crank',3,1,'Which tool is a crank?',['a bent handle attached to a rotating axle','a flat sheet of paper','a courtroom witness'],'a bent handle attached to a rotating axle','The handle’s shape and connection to a shaft identify the mechanism.'),Q('crank',4,2,'The operator cranked the winch until the gate rose. What did the operator do?',['turned the mechanism by its handle','painted the gate','argued against the gate'],'turned the mechanism by its handle','Crank as a verb means turn or operate with a crank.') ]});

  D('crass',{etymology:E('Crass came directly from Latin crassus “thick, coarse,” and developed the figurative sense “grossly insensitive or stupid.”','crass'),contexts:[C('crass.s1','社交礼仪','When a colleague mentioned her father’s death, Mark made a joke about inheritance; the crass remark ignored her grief and left the table silent.','同事提到父亲去世时，马克开了个关于遗产的玩笑；这句粗俗无礼的话无视她的悲痛，让全桌安静下来。','When a colleague mentioned her father’s death / Mark made a joke about inheritance / the crass remark ignored her grief / and left the table silent.','crass 修饰 remark；分句说明言论冒犯人的原因和效果。','在哀伤场合拿遗产开玩笑，表现出粗俗、缺乏体察。')],mistakes:[M('Her sensitive condolence note was crass: it acknowledged the loss gently and offered help without asking anything in return.','Her insensitive joke about the bereavement was crass; her condolence note was considerate.','体贴的慰问并不粗俗；crass 用于冒犯、愚钝或缺少感受力的行为。')],quiz:[Q('crass',1,1,'A crass comment is likely?',['offensively crude or insensitive','thoughtful and tactful','a very small bay'],'offensively crude or insensitive','Crass describes behaviour that offends good sense or feeling.'),Q('crass',2,1,'Which remark is most crass at a memorial?',['joking that the family should hurry up and inherit','quietly offering condolences','asking whether someone needs a ride home'],'joking that the family should hurry up and inherit','The joke is insensitive to the family’s grief.'),Q('crass',3,1,'The adjective crass can also suggest?',['stupidly coarse or lacking good judgment','carefully researched','secret but legally authorized'],'stupidly coarse or lacking good judgment','Crass may condemn both insensitivity and gross stupidity.'),Q('crass',4,1,'Choose the natural use.',['His crass interruption offended the guests.','The crass bay was sheltered by cliffs.','She crassly a contract.'],'His crass interruption offended the guests.','The adjective describes an offensive, insensitive interruption.') ]});

  D('craven',{etymology:E('Craven comes from Old French cravant, “defeated, vanquished,” and became an adjective for shamefully cowardly; it can also be a noun for such a person.','craven'),contexts:[C('craven.s1','勇气与职责','The review called the official’s silence craven because he knew the safety report had been falsified yet refused to speak while workers remained at risk.','评论称那名官员的沉默怯懦可鄙，因为他明知安全报告造假，却在工人仍身处危险时拒绝发声。','The review called the official’s silence craven / because he knew the safety report had been falsified / yet refused to speak / while workers remained at risk.','call + 名词 + adjective complement；because 从句说明可鄙的怯懦表现。','明知他人受险仍因害怕而逃避职责，符合贬义“怯懦的” s1。')],mistakes:[M('The review praised the craven official for boldly exposing the danger despite threats and accepting the personal risk.','The review praised the courageous official for exposing the danger despite threats.','挺身承担风险属于勇敢；craven 指可鄙的怯懦。','confusable')],quiz:[Q('craven',1,1,'A craven choice is?',['shamefully cowardly','bold and honourable','a type of fresh-water animal'],'shamefully cowardly','Craven is a strongly disapproving adjective for lacking courage.'),Q('craven',2,2,'The noun a craven refers to?',['a person who is shamefully afraid','a skilled craftworker','a local councillor'],'a person who is shamefully afraid','As a noun it labels a cowardly person.'),Q('craven',3,1,'Which action might be called craven?',['an official hides the truth to avoid a small personal risk while others suffer','a rescuer enters a safe area to guide people out','a witness tells the truth despite pressure'],'an official hides the truth to avoid a small personal risk while others suffer','The official avoids a duty through contemptible fear.'),Q('craven',4,1,'Choose the closest opposite of craven.',['courageous','fearful','cowardly'],'courageous','Craven and courageous have contrasting meanings.','confusable')]});

  D('crayfish',{etymology:E('Crayfish, also spelled crawfish, is a reshaping of Middle English crevis from Old French crevice, related to German Krebs; the ending was reinterpreted as fish.','crayfish'),contexts:[C('crayfish.s1','淡水生态','The children returned the crayfish to the stream after observing its claws and hard shell, taking care not to keep the freshwater animal in a warm, dry bucket.','孩子们观察了小龙虾的螯和硬壳后把它放回溪流，小心不把这种淡水动物留在温暖干燥的桶里。','The children returned the crayfish to the stream / after observing its claws and hard shell / taking care not to keep the freshwater animal / in a warm, dry bucket.','crayfish 是淡水甲壳动物；after 引导观察后归还的时间状语。','有螯、有硬壳并生活在溪流，符合淡水螯虾义。')],mistakes:[M('The guide identified the crayfish as a large marine whale with lungs and no shell.','The guide identified the crayfish as a small lobster-like freshwater animal with a hard shell.','crayfish 是小型淡水甲壳动物，不是大型鲸类。','confusable')],quiz:[Q('crayfish',1,1,'A crayfish is a small animal that usually lives in?',['fresh water','desert sand','a cottonwood tree'],'fresh water','Crayfish are lobster-like animals that live in fresh water.'),Q('crayfish',2,1,'Which creature has claws, a hard shell, and lives in a stream?',['crayfish','coyote','cougar'],'crayfish','Those features fit a freshwater crayfish.'),Q('crayfish',3,1,'Crayfish are most closely associated with?',['crabs and lobsters','mammals such as mountain lions','flowering poplar trees'],'crabs and lobsters','They are small crustacean relatives of lobsters.'),Q('crayfish',4,1,'A student found a tiny lobster-like animal beneath a freshwater rock. It may be a?',['crayfish','courier','courtship'],'crayfish','Crayfish inhabit freshwater streams and similar places.') ]});

  D('creativity',{etymology:E('Creativity is create plus -ive and the noun-forming suffix -ity; create came through Old French from Latin creare “bring forth or produce.”','creativity'),contexts:[C('creativity.s1','设计教育','The class used creativity to turn discarded cartons into a working model of a flood barrier, testing several shapes before choosing one that held back the most water.','全班发挥创造力，把废纸盒做成可用的防洪屏障模型；他们先测试几种形状，再选出挡水效果最好的一种。','The class used creativity / to turn discarded cartons into a working model of a flood barrier / testing several shapes / before choosing one that held back the most water.','use creativity to do 表示用创造力完成任务；testing 说明探索方案的过程。','提出并测试新颖做法以解决实际问题，体现创造能力。')],mistakes:[M('The student showed creativity by copying the finished design exactly and refusing to consider any new approach.','The student showed creativity by developing and testing an original design for the barrier.','不加思考地照抄既有方案本身不能体现产生原创想法的能力。')],quiz:[Q('creativity',1,1,'Creativity is the ability to?',['produce original ideas or works','memorize a fixed list only','borrow money and repay it'],'produce original ideas or works','Creativity means the capacity for original thought or production.'),Q('creativity',2,1,'A team tries several novel ways to reuse waste. It is using?',['creativity','credence','courtship'],'creativity','Trying original approaches is creative work.'),Q('creativity',3,1,'Which result best demonstrates creativity?',['an original solution to a design problem','a verbatim copy of an existing answer','a receipt for a loan'],'an original solution to a design problem','Original work or ideas demonstrate creativity.'),Q('creativity',4,1,'The suffix -ity in creativity helps form a noun naming?',['a quality or capacity','a person who carries a parcel','a past-tense action'],'a quality or capacity','-ity often forms an abstract quality noun.') ]});

  D('credence',{etymology:E('Credence came through Old French credence from Medieval Latin credentia, “belief or trust,” related to Latin credere “believe.” A separate liturgical sense names a small altar-side table.','credence'),contexts:[C('credence.s1','证据评估','The leaked message gained little credence because its timestamp contradicted the server log, and no independent witness could confirm who had sent it.','这条泄露的消息没获得多少采信，因为时间戳与服务器日志矛盾，也没有独立证人能确认发送者。','The leaked message gained little credence / because its timestamp contradicted the server log / and no independent witness / could confirm who had sent it.','gain credence 表示获得信任；because 给出证据不足的理由。','可核查记录互相矛盾且无人独立证实，所以主张难以被相信。')],mistakes:[M('The investigator gave the anonymous claim full credence despite contradictory records and no supporting evidence.','The investigator gave the anonymous claim little credence because records contradicted it.','面对相互矛盾的记录仍不加辨别地全盘相信，与 credence 所表示的采信判断不相称。')],quiz:[Q('credence',1,1,'To give a report credence is to?',['accept it as believable','turn it into a courtroom','prove it is false before reading it'],'accept it as believable','Credence is acceptance of something as true.'),Q('credence',2,2,'In a church inventory, a credence is a?',['small side table for vessels near the altar','written argument opposing a claim','forest thicket for animals'],'small side table for vessels near the altar','The liturgical noun names a small table near the altar.'),Q('credence',3,1,'Conflicting records may make a claim lose?',['credence','coverage','creativity'],'credence','Credence refers to the belief or trust given to a claim.'),Q('credence',4,1,'“The rumor lacks credence” means?',['people have little reason to accept it as true','it is a kind of altar furniture','it has many supporting witnesses'],'people have little reason to accept it as true','The statement says the rumor is not believed or trusted.') ]});

  D('credentialism',{etymology:E('Credentialism is credential plus -ism, naming a doctrine or practice. Credential comes from French crédential and Medieval Latin credentialis, related to credere “believe or entrust.”','credentialism'),contexts:[C('credentialism.s1','招聘政策','The firm challenged credentialism by testing applicants’ practical skills and work samples instead of rejecting capable candidates who lacked a prestigious degree.','公司通过测试求职者的实际技能和作品来反对文凭主义，而不是淘汰缺少名校学位但有能力的候选人。','The firm challenged credentialism / by testing applicants’ practical skills and work samples / instead of rejecting capable candidates / who lacked a prestigious degree.','challenge credentialism；instead of 引出以能力评估代替只看文凭的做法。','招聘把技能放在资格纸面证明之前，针对的正是过度依赖文凭的做法。')],mistakes:[M('The hiring policy was credentialism because it judged every applicant by demonstrated skills and never considered diplomas.','The hiring policy rejected credentialism by judging applicants on demonstrated skills rather than diplomas.','只看实际技能、完全不依赖文凭并不属于以资格证书为主要标准的 credentialism。')],quiz:[Q('credentialism',1,1,'Credentialism is the practice of judging people mainly by?',['degrees and licences rather than demonstrated skill','how many original ideas they generate','the parcels they deliver'],'degrees and licences rather than demonstrated skill','Credentialism overvalues formal qualifications as a measure of ability.'),Q('credentialism',2,1,'A company rejects experienced workers solely because they lack a particular diploma. This is?',['credentialism','courtship','countercurrent'],'credentialism','The decision relies primarily on credentials rather than ability.'),Q('credentialism',3,1,'What would a critic of credentialism likely support?',['assessing relevant skills alongside qualifications','requiring more diplomas for every task regardless of need','ignoring all work samples'],'assessing relevant skills alongside qualifications','The criticism opposes treating diplomas as the main proxy for competence.'),Q('credentialism',4,1,'The suffix -ism in credentialism signals?',['a system or practice','a small animal','a person who advises a court'],'a system or practice','-ism forms a noun for a doctrine, system, or practice.') ]});

  D('credentials',{etymology:E('Credentials is the plural of credential, from French crédential and Medieval Latin credentialis, “that which gives authority or credibility,” related to credere “believe.”','credentials'),contexts:[C('credentials.s1','身份核验','At the border, the officer checked the journalist’s press credentials and passport before allowing her to enter the restricted area.','在边境，官员检查记者的新闻证件和护照后，才准许她进入限制区域。','At the border / the officer checked the journalist’s press credentials and passport / before allowing her / to enter the restricted area.','credentials 常作复数，指证明身份或资格的文件；before allowing 引出核验后的决定。','记者出示用来证明其身份和通行资格的文件，符合 s1。')],mistakes:[M('The candidate showed their credentials, which proved the candidate had no training, no identity, and no qualifications at all.','The candidate showed credentials documenting identity, training, and qualifications.','credentials 是证明身份或能力的材料，不会用来证明这些资质完全不存在。')],quiz:[Q('credentials',1,1,'A visitor presents credentials at a secured laboratory to prove?',['identity and authorization','a counterexample in mathematics','the weight of a parcel'],'identity and authorization','Credentials are documents that prove identity or qualifications.'),Q('credentials',2,2,'A reviewer says an applicant’s long record of successful projects gives her credentials for the role. Here credentials means?',['achievements showing fitness for a job','only plastic identity cards','an opposing current in a pipe'],'achievements showing fitness for a job','Credentials can figuratively mean achievements that qualify a person.'),Q('credentials',3,1,'The noun credentials is usually?',['plural in form','a singular verb meaning to certify','an adjective meaning secret'],'plural in form','The word is normally used as a plural noun.'),Q('credentials',4,1,'Which item is a credential?',['a licence documenting professional qualification','an unsigned rumor','a water current'],'a licence documenting professional qualification','A credential is evidence of qualification or identity.') ]});

  D('credibility',{etymology:E('Credibility is credible plus -ity; credible came through French from Latin credibilis “worthy of belief,” related to credere “believe.”','credibility'),contexts:[C('credibility.s1','新闻核实','The reporter’s credibility improved after she published the source documents, corrected a mistaken date, and clearly separated verified facts from witnesses’ guesses.','记者公开了来源文件、纠正了错误日期，并明确区分已核实事实与证人的猜测后，她的可信度提高了。','The reporter’s credibility improved / after she published the source documents / corrected a mistaken date / and clearly separated verified facts from witnesses’ guesses.','credibility 表示令人愿意相信的品质；after 从句列出提升信任的行动。','公开证据并更正错误增强了受众相信她及其报道的理由。')],mistakes:[M('The spokesperson’s credibility rose after investigators proved that every statement was fabricated and contradicted by records.','The spokesperson’s credibility fell after investigators proved that the statements were fabricated.','被证实捏造通常削弱可信度，不会提升它。')],quiz:[Q('credibility',1,1,'A source has credibility when people?',['have reason to believe it','know it has been fabricated','cannot understand its language'],'have reason to believe it','Credibility is the quality of being believable or trustworthy.'),Q('credibility',2,1,'Publishing original documents may increase a reporter’s?',['credibility','cramming','crassness'],'credibility','Verifiable evidence gives readers more reason to trust the report.'),Q('credibility',3,1,'Repeated factual errors can damage a speaker’s?',['credibility','courtship','coverage area'],'credibility','Errors can make people less willing to believe a speaker.'),Q('credibility',4,1,'The suffix -ity in credibility names?',['a quality or state','a person carrying mail','a legal room'],'a quality or state','Credibility names the quality that makes a claim or person believable.') ]});

  D('creditor',{etymology:E('Creditor comes from Latin creditor, “lender or one who trusts,” from credere “believe, entrust”; it names someone owed money or payment.','creditor'),contexts:[C('creditor.s1','债务偿还','The creditor agreed to extend the repayment deadline after the small supplier showed invoices proving that the overdue payment had not yet arrived from its client.','小供应商出示发票证明客户的欠款尚未到账后，债权人同意延长还款期限。','The creditor agreed to extend the repayment deadline / after the small supplier showed invoices / proving that the overdue payment had not yet arrived / from its client.','creditor 是等待收款的一方；agree to extend 表示同意延长期限。','供应商欠该方款项，因此对方是债权人。')],mistakes:[M('The creditor borrowed money from the supplier and owed the supplier the repayment.','The debtor borrowed money from the creditor and owed the creditor repayment.','借入资金并负有还款义务的是 debtor；creditor 是有权收款的一方。','confusable')],quiz:[Q('creditor',1,1,'A creditor is someone who?',['is owed money','owes money to a lender','delivers parcels'],'is owed money','A creditor has lent money or supplied goods and is due payment.'),Q('creditor',2,1,'If a shop buys goods on credit, the supplier who must be paid is the?',['creditor','debtor','courier'],'creditor','The supplier is owed payment.'),Q('creditor',3,1,'Who is the creditor in a loan?',['the lender awaiting repayment','the borrower making repayment','the witness to the agreement'],'the lender awaiting repayment','The lender is the person to whom the debt is owed.'),Q('creditor',4,1,'Choose the accurate relation.',['The debtor owes the creditor.','The creditor owes the debtor by definition.','A creditor is a court building.'],'The debtor owes the creditor.','Creditor and debtor describe opposite sides of a debt.') ]});

  D('credulous',{etymology:E('Credulous came from Latin credulus “believing too readily,” related to credere “believe”; -ous forms an adjective. It is often critical of insufficient skepticism.','credulous'),contexts:[C('credulous.s2','网络诈骗','The credulous buyer transferred money to a stranger who promised a guaranteed prize, never checking the official contest rules or asking for proof.','轻信的买家把钱转给承诺保证中奖的陌生人，既没有核实官方竞赛规则，也没有索要证据。','The credulous buyer transferred money to a stranger / who promised a guaranteed prize / never checking the official contest rules / or asking for proof.','credulous 修饰 buyer；现在分词描述其轻信的行为。','面对无证据的保证便汇款，说明容易被人骗，符合 s2。')],mistakes:[M('She was credulous because she demanded independent evidence before believing a stranger’s prize claim.','She was skeptical because she demanded independent evidence before believing the stranger’s claim.','要求独立证据表明谨慎怀疑，不是 credulous 的轻信态度。','confusable')],quiz:[Q('credulous',1,2,'A credulous person is especially?',['easy to trick because they trust too quickly','difficult to deceive because they check evidence','qualified to advise a court'],'easy to trick because they trust too quickly','The second sense emphasizes susceptibility to deception.'),Q('credulous',2,1,'Someone believes a wild rumor without checking any source. The person is?',['credulous','skeptical','courtly'],'credulous','Credulous means ready to believe claims without enough proof.'),Q('credulous',3,1,'Which action suggests a credulous attitude?',['sending money to an unverified stranger who promises a prize','checking a claim against official records','asking for independent confirmation'],'sending money to an unverified stranger who promises a prize','Trusting an unsupported promise makes the person easy to deceive.'),Q('credulous',4,1,'The ending -ous in credulous helps form?',['an adjective','a plural-only noun','a verb meaning to borrow'],'an adjective','Credulous is an adjective describing a person’s readiness to believe.') ]});

  D('creeper',{etymology:E('Creeper is creep plus the agent or instrument suffix -er. Creep came from Old English creopan “move slowly”; the noun can be a trailing plant or a slow-moving person, animal, or vehicle.','creeper'),contexts:[C('creeper.s1','园艺植物','The gardener trained the creeper along a wire frame so its stems covered the bare wall without climbing into the neighbouring window.','园丁把攀缘植物引到铁丝架上，让枝蔓覆盖裸墙，又不至于爬进邻居的窗户。','The gardener trained the creeper along a wire frame / so its stems covered the bare wall / without climbing into the neighbouring window.','train a creeper along a support；so 引导预期结果。','茎蔓沿支架攀爬并覆盖墙面，符合攀缘植物义 s1。')],mistakes:[M('The gardener called the creeper a tree whose stiff trunk stood upright and whose stems never climbed or trailed.','The gardener called the climbing vine a creeper because its stems trailed along the wall.','不攀缘也不蔓生的直立树木不符合植物义 creeper。')],quiz:[Q('creeper',1,1,'A garden creeper is a plant that?',['climbs or trails along a surface','swims in fresh water','delivers parcels'],'climbs or trails along a surface','The plant sense refers to stems that climb or trail.'),Q('creeper',2,2,'A slow-moving military vehicle may be called a creeper because it?',['moves slowly, gradually along','grows roots on a wall','gives legal advice'],'moves slowly, gradually along','The other noun sense can name a person, animal, or vehicle that moves slowly.'),Q('creeper',3,1,'Which plant is most likely a creeper?',['a vine spreading across a trellis','a tall tree with a bare straight trunk','a water current'],'a vine spreading across a trellis','A creeper climbs or trails along a support.'),Q('creeper',4,1,'The suffix -er in creeper contributes a noun for?',['something characterized by creeping','a past-tense verb only','a court building'],'something characterized by creeping','The noun names a plant or mover associated with creeping.') ]});

  D('Crescent',{etymology:E('Crescent came through Old French croissant from Latin crescere “grow”; the moon appears to grow from a thin curved sliver, and the noun also names that shape.','crescent'),contexts:[C('Crescent.s1','天文观察','A thin crescent hung above the rooftops just after sunset, with only a narrow curved strip of the Moon illuminated against the darkening sky.','日落后不久，一弯细月挂在屋顶上方，只有月亮狭窄弯曲的一部分被照亮，映在渐暗的天空中。','A thin crescent hung above the rooftops / just after sunset / with only a narrow curved strip of the Moon illuminated / against the darkening sky.','crescent 作名词指新月或新月形物；with 结构补充被照亮的部分。','月面仅呈细弯弧形，符合弯月义 s1。')],mistakes:[M('The crescent Moon looked like a perfectly round full disk, with no curved edge or thin illuminated sliver.','The crescent Moon looked like a thin curved sliver, not a full disk.','圆满整圆的月亮不是弯月形的 crescent。')],quiz:[Q('Crescent',1,1,'A crescent Moon appears as?',['a thin curved illuminated sliver','a completely dark square','a full circle with every part equally lit'],'a thin curved illuminated sliver','The lunar sense is the Moon as a narrow curve.'),Q('Crescent',2,2,'A crescent-shaped island is?',['curved like a thin arc','perfectly rectangular','a type of legal document'],'curved like a thin arc','Crescent can be an adjective describing that curved shape.'),Q('Crescent',3,1,'A jeweller sells a pendant shaped like a crescent. The pendant resembles?',['a curved sliver of a Moon','a straight ruler','a square courthouse'],'a curved sliver of a Moon','The noun can refer to any object with the crescent outline.'),Q('Crescent',4,2,'Choose the correct use.',['A crescent-shaped bay curves around the shore.','The crescent-shaped table had four square corners only.','Crescently is the name of the moon.'],'A crescent-shaped bay curves around the shore.','The adjective sense means shaped like a crescent.') ]});

  D('cretaceous',{etymology:E('Cretaceous derives from Latin creta “chalk” plus the geological-period suffix -aceous; the period name refers to abundant chalk deposits, especially in Europe.','cretaceous'),contexts:[C('cretaceous.s2','地质年代','The museum label dates the fossil to the Cretaceous, the final period of the Mesozoic, when many dinosaurs still lived before the mass extinction.','博物馆标签把这块化石定年为白垩纪，这是中生代的最后一个时期，许多恐龙仍生活于其中，之后发生大灭绝。','The museum label dates the fossil to the Cretaceous / the final period of the Mesozoic / when many dinosaurs still lived / before the mass extinction.','the Cretaceous 作专名名词指地质时期；when 从句说明时期特征。','化石被归入中生代末期这一地质时期，符合 s2。')],mistakes:[M('The Cretaceous was the first year of the twenty-first century and came after modern industrial history.','The Cretaceous was a geological period near the end of the Mesozoic, millions of years ago.','白垩纪是远古地质时期，不是现代公历年份。')],quiz:[Q('cretaceous',1,2,'The Cretaceous is a period in?',['geological history','a modern school term','an annual court calendar'],'geological history','The noun names a geologic period about 145 to 66 million years ago.'),Q('cretaceous',2,1,'A Cretaceous fossil is from?',['the last period of the Mesozoic','the present decade','a medieval court'],'the last period of the Mesozoic','The adjective means belonging to the Cretaceous period.'),Q('cretaceous',3,1,'Chalk deposits help explain the word Cretaceous because creta is Latin for?',['chalk','river','council'],'chalk','The geological name derives from Latin for chalk.'),Q('cretaceous',4,2,'Which label uses cretaceous as a noun?',['“The Cretaceous ended about 66 million years ago.”','“The cretaceous layer is chalky.”','“He cretaceously signed the form.”'],'“The Cretaceous ended about 66 million years ago.”','Capitalized The Cretaceous names the geological period itself.') ]});

  D('crevasse',{etymology:E('Crevasse came through French crevasse from Old French crever “burst or break”; it denotes a deep crack, especially in glacier ice, and by extension a breach in a levee.','crevasse'),contexts:[C('crevasse.s1','冰川徒步','The guide roped the team together before crossing the snow bridge, because a deep crevasse beneath it was hidden by a thin crust of fresh snow.','穿越雪桥前，向导把队伍用绳子连在一起，因为桥下有一道深冰隙，被薄薄的新雪层遮住了。','The guide roped the team together / before crossing the snow bridge / because a deep crevasse beneath it / was hidden by a thin crust of fresh snow.','crevasse 指冰川深裂缝；because 从句说明必须结绳的危险原因。','被雪覆盖的冰川深裂缝会造成坠落风险，符合该义。')],mistakes:[M('The climbers stepped into a crevasse, a shallow painted line on a dry indoor floor with no depth.','The climbers avoided the crevasse, a deep open crack hidden in the glacier.','无深度的地面彩线不符合 crevasse 的深裂缝或堤坝决口义。')],quiz:[Q('crevasse',1,1,'A crevasse on a glacier is?',['a deep open crack in the ice','a small court table','a patch of lawn weed'],'a deep open crack in the ice','The word commonly names a deep crack in a glacier.'),Q('crevasse',2,1,'A flood barrier breaks open along a long gap. The breach may be called a?',['crevasse','courtship','credential'],'crevasse','Crevasse can also mean a breach in a levee.'),Q('crevasse',3,1,'Why do climbers rope together near a crevasse?',['the hidden crack can be deep and dangerous','it is a warm shelter for cattle','it is a legal hearing room'],'the hidden crack can be deep and dangerous','A crevasse is a deep opening that can be concealed by snow.'),Q('crevasse',4,2,'In “the quake crevassed the ice,” crevasse is used as?',['a verb meaning to split with a deep crack','an adjective meaning courteous','a noun for a courier'],'a verb meaning to split with a deep crack','The word can be used as a verb for opening a deep crack.') ]});

  D('crevice',{etymology:E('Crevice came through Old French crevace from crever “to burst,” related to the source of crevasse; the noun is a narrow opening or split in a hard surface.','crevice'),contexts:[C('crevice.s2','石墙修缮','Rainwater seeped into a narrow crevice between the old stones, froze overnight, and widened the small split enough to loosen the outer face of the wall.','雨水渗进旧石块之间狭窄的裂隙，夜间结冰后把小缝撑大，足以使墙体外侧松动。','Rainwater seeped into a narrow crevice between the old stones / froze overnight / and widened the small split / enough to loosen the outer face of the wall.','crevice 可指小裂口；enough to 引出裂口扩大的后果。','小裂缝夹在石块之间并能让水进入，符合 s2。')],mistakes:[M('The mason filled a crevice that was actually a wide open doorway several metres across.','The mason filled a narrow crevice between the stones.','宽阔门洞不是狭窄的小裂口；两者尺度和形状不同。')],quiz:[Q('crevice',1,1,'A crevice in a rock is a?',['narrow opening or crack','large flat field','court official'],'narrow opening or crack','Crevice means a narrow split in rock, wall, or another hard surface.'),Q('crevice',2,2,'A coin slips into a tiny crevice in the floor. Here crevice emphasizes?',['a small split things can fall into','a wide doorway','a current of water'],'a small split things can fall into','The second sense stresses a small opening that can trap objects.'),Q('crevice',3,1,'Where might a geologist find a crevice?',['between two sections of rock','in a clear blue sky','on a courtroom verdict'],'between two sections of rock','A crevice is a narrow opening in a hard surface.'),Q('crevice',4,1,'Choose the natural phrase.',['a crevice in the stone wall','a crevice of a trained adviser','a crevice that means to counsel'],'a crevice in the stone wall','The noun naturally names a crack in a solid surface.') ]});

  D('crib',{etymology:E('Crib comes from Old English crib(b), a manger or feeding rack, and later named a child’s barred bed; the slang verb “copy” developed separately from the sense of borrowing or stealing.','crib'),contexts:[C('crib.s2','学术诚信','The teacher compared the two essays and found that one student had cribbed several paragraphs from a website without quotation marks or a citation.','老师比较两篇作文后发现，一名学生从网站抄了几段文字，却没有加引号或注明出处。','The teacher compared the two essays / and found that one student had cribbed several paragraphs from a website / without quotation marks or a citation.','crib 作俚语动词表示抄袭；without 说明未标出处。','学生把他人文字冒充自己的作业，符合抄袭义 s2。')],mistakes:[M('The student cribbed the essay by writing every paragraph from original research and clearly citing all quoted passages.','The student cribbed the essay by copying uncited paragraphs from another writer.','原创写作并规范引用不是抄袭；crib 此义要求未经承认地照抄。')],quiz:[Q('crib',1,2,'To crib in an exam is to?',['copy another person’s work dishonestly','put a baby to bed','feed a horse'],'copy another person’s work dishonestly','The verb means to copy someone else’s work and present it as your own.'),Q('crib',2,1,'In British usage, a baby may sleep in a?',['crib','crevasse','courier'],'crib','Crib can name a child’s bed with high barred sides.'),Q('crib',3,1,'A farmer’s crib may be used as?',['a manger or feed rack for animals','a legal adviser','a water current'],'a manger or feed rack for animals','The older noun sense is a rack or container for animal feed.'),Q('crib',4,2,'Which sentence uses crib as a verb?',['He cribbed the answer from his neighbour.','The infant slept in a crib.','The cow ate from the crib.'],'He cribbed the answer from his neighbour.','Here cribbed means copied dishonestly.') ]});

  D('crimp',{etymology:E('Crimp is related to Dutch krimpen “to shrink or contract”; English developed senses of a small fold and of pressing folds or compressing an end.','crimp'),contexts:[C('crimp.s2','电线连接','The technician crimped the copper sleeve tightly around the two wire ends, then tugged the connection to make sure the metal joint would not slip free.','技术员把铜套管压接在两根电线末端，然后拉了拉接头，确认金属连接不会松脱。','The technician crimped the copper sleeve tightly around the two wire ends / then tugged the connection / to make sure the metal joint would not slip free.','crimp 作动词表示压紧形成牢固连接；to make sure 说明检验目的。','工具压缩金属套管并固定电线接头，符合压接义 s2。')],mistakes:[M('The technician crimped the wire joint by leaving the sleeve loose enough to slide off without resistance.','The technician crimped the wire joint by compressing the sleeve tightly around the ends.','未压紧、能轻易滑脱不构成 crimping 接头。')],quiz:[Q('crimp',1,1,'A crimp in cloth is a?',['small fold or wave','large courtroom','deep glacier opening'],'small fold or wave','The noun can mean a small fold or crease.'),Q('crimp',2,2,'To crimp a wire connector is to?',['press it tightly around the wire ends','paint it without changing its shape','cut it into a long ribbon'],'press it tightly around the wire ends','The verb can mean compressing a fitting to secure it.'),Q('crimp',3,1,'A hair stylist may crimp hair to?',['form small waves or folds','make it completely straight and flat','turn it into a legal contract'],'form small waves or folds','Crimping presses small waves into hair.'),Q('crimp',4,2,'The mechanic crimped the metal band around the hose. What happened?',['the band was pressed into a tighter fastening','the hose was carried to court','the metal grew a plant stem'],'the band was pressed into a tighter fastening','The verb sense describes pressing material into a fold or secure joint.') ]});

  D('crinkle',{etymology:E('Crinkle is a frequentative form related to crinkle/crinkle-like words for curling or wrinkling; it can name small creases or the action of forming them.','crinkle'),contexts:[C('crinkle.s2','纸张整理','She crinkled the foil around the sandwich, pressing the loose edges together so the filling would not spill during the walk to school.','她把锡纸在三明治周围捏出褶皱，将松散边缘压在一起，防止上学路上馅料漏出。','She crinkled the foil around the sandwich / pressing the loose edges together / so the filling would not spill / during the walk to school.','crinkle 作动词表示使起细皱；pressing 描写操作，so 引出目的。','锡纸因挤压形成细小褶皱，符合动词义 s2。')],mistakes:[M('The sheet remained perfectly smooth and flat, but the report said it crinkled into many small folds.','The sheet formed small folds when she crinkled it in her hand.','完全平整无皱与 crinkle 所描述的产生细小褶皱相矛盾。')],quiz:[Q('crinkle',1,1,'A crinkle in paper is?',['a small crease or wavy fold','a very large bay','a person who advises a court'],'a small crease or wavy fold','Crinkle can name a slight crease or wave.'),Q('crinkle',2,2,'To crinkle a wrapper is to?',['make it form small folds','deliver it to a courthouse','stretch it until perfectly smooth'],'make it form small folds','The verb means to form or cause small creases.'),Q('crinkle',3,1,'Which sound might a crinkle make?',['a dry wrapper being squeezed','a silent stone wall','a court ruling read aloud'],'a dry wrapper being squeezed','Wrinkling a wrapper often makes a crinkling sound.'),Q('crinkle',4,2,'“The leaves crinkled underfoot” means they?',['formed or made a series of small folds','served as legal credentials','grew into a large tree'],'formed or made a series of small folds','The verb can describe something forming small wrinkles.') ]});

  D('crippling',{etymology:E('Crippling is the present participle/adjective from cripple plus -ing; cripple is related to Old English crypel, “a person with a disabled limb.” Figuratively crippling means severely disabling or damaging.','crippling'),contexts:[C('crippling.s1','公共财政','After the bridge closed, the only detour added forty minutes to each delivery and fuel costs doubled, creating a crippling burden for the island’s small shops.','桥梁关闭后，唯一的绕行路线让每次送货多花四十分钟，燃油成本翻倍，给岛上小商店造成沉重打击。','After the bridge closed / the only detour added forty minutes to each delivery / and fuel costs doubled / creating a crippling burden for the island’s small shops.','crippling 修饰 burden，表示严重到妨碍正常经营；creating 分词引出结果。','严重成本足以妨碍店铺运营，符合“造成重创”的比喻义。')],mistakes:[M('The minor fee was crippling, yet it had no effect on the shop’s budget, operations, or ability to pay.','The doubled fuel bill was crippling because it threatened the shop’s ability to stay open.','毫无影响的小额费用不构成使人或活动严重受损的 crippling burden。')],quiz:[Q('crippling',1,1,'A crippling cost is one that?',['is so severe it seriously harms an activity or budget','is too small to notice','is paid only in cash'],'is so severe it seriously harms an activity or budget','Crippling means severe enough to disable or wreck something.'),Q('crippling',2,1,'A crippling injury may?',['leave a person unable to function normally','improve every movement','refer to a legal adviser'],'leave a person unable to function normally','The literal sense concerns severe physical disability.'),Q('crippling',3,1,'Which debt is most likely crippling for a small shop?',['payments so large they threaten its survival','a tiny fee already covered by the budget','a bill that is canceled'],'payments so large they threaten its survival','The figurative sense emphasizes severe damage or threat.'),Q('crippling',4,1,'Choose the natural phrase.',['crippling losses after the factory closed','crippling sunshine measured by the hour','a crippling that delivered the letter'],'crippling losses after the factory closed','The adjective commonly describes severe losses or constraints.') ]});

  D('criss-cross',{etymology:E('Criss-cross is a reduplicated form associated with the letters X and the cross mark; it describes intersecting lines or paths and can also name a crossed-line pattern.','criss-cross'),contexts:[C('criss-cross.s1','城市道路','Bike lanes criss-cross the new district, connecting the riverside path with schools, markets, and two railway stations.','自行车道纵横交错地穿过新区，把河边步道、学校、市场和两个火车站连接起来。','Bike lanes criss-cross the new district / connecting the riverside path / with schools, markets, and two railway stations.','criss-cross 作形容词修饰 lanes，表示路线彼此交叉；connecting 补充连接作用。','多条车道相互穿行并连接各处，符合纵横交错义 s1。')],mistakes:[M('The criss-cross lanes ran as a single parallel line and never met or intersected anywhere.','The criss-cross lanes intersected one another at several junctions.','永不相交的平行路线没有 criss-cross 所要求的交叉关系。')],quiz:[Q('criss-cross',1,1,'Criss-cross lines?',['intersect one another','run only in one unbroken parallel line','form a single circle with no crossing'],'intersect one another','The adjective describes lines or paths that cross repeatedly.'),Q('criss-cross',2,2,'A criss-cross is also?',['a mark or network made of crossing lines','a person who delivers parcels','a debt owed to a lender'],'a mark or network made of crossing lines','The noun names a crossed-line mark or pattern.'),Q('criss-cross',3,1,'A fence pattern made from repeated diagonal crossings is?',['criss-cross','courtly','counterproductive'],'criss-cross','The repeated intersections create a criss-cross pattern.'),Q('criss-cross',4,1,'Choose the accurate description.',['Trails criss-cross the forest in several directions.','A single straight trail criss-crosses itself without turning.','Criss-cross means an insurance limit.'],'Trails criss-cross the forest in several directions.','Paths running across one another in multiple directions criss-cross.') ]});

  D('crisscross',{etymology:E('Crisscross combines the same cross-shaped reduplicative element as criss-cross; without the hyphen it is commonly a verb meaning to travel repeatedly across or to mark with intersecting lines.','crisscross'),contexts:[C('crisscross.s1','道路规划','Delivery vans crisscross the county each morning, carrying supplies from the central depot to towns on both sides of the mountain range.','每天早晨，送货车在全县各处往来穿行，把物资从中央仓库运往山脉两侧的城镇。','Delivery vans crisscross the county each morning / carrying supplies from the central depot / to towns on both sides of the mountain range.','crisscross 作动词表示在多方向反复穿行；carrying 说明运输任务。','车辆往返穿越全县各地，符合动词义 s1。')],mistakes:[M('The vans crisscrossed the county by staying parked at one depot all day and never travelling anywhere.','The vans crisscrossed the county by travelling between towns in several directions.','一直停在原地并未穿越任何地方，不能称为 crisscross。')],quiz:[Q('crisscross',1,1,'To crisscross a region is to?',['travel across it in many directions','stay in one spot without moving','raise a legal objection'],'travel across it in many directions','The verb means to travel repeatedly across a place.'),Q('crisscross',2,2,'To crisscross a page with pencil marks means to?',['draw lines that cross one another','erase every mark without replacement','fold the page into a cot'],'draw lines that cross one another','The verb can mean making a pattern of crossing lines.'),Q('crisscross',3,1,'Which sentence uses crisscross as a verb?',['Footpaths crisscross the park from gate to gate.','The crisscross was pinned to his coat.','The crisscrossed is a counsellor.'],'Footpaths crisscross the park from gate to gate.','Here the paths travel across the park in intersecting directions.'),Q('crisscross',4,2,'The children crisscrossed the map in red pencil. They?',['marked it with intersecting lines','sent it by courier','used it to house a trial'],'marked it with intersecting lines','As a verb, crisscross can mean to mark with crossing lines.') ]});

  D('critic',{etymology:E('Critic came through French critique from Greek kritikos “able to judge,” related to krinein “separate, decide.” It can be an evaluator of art or a person who criticizes.','critic'),contexts:[C('critic.s1','艺术评论','The critic praised the novel’s precise dialogue but argued that the final chapter resolved the mystery too quickly, supporting each judgment with passages from the text.','评论家赞扬小说对白精准，却认为最后一章过快解开谜团，并用文中段落支持每项判断。','The critic praised the novel’s precise dialogue / but argued that the final chapter resolved the mystery too quickly / supporting each judgment / with passages from the text.','critic 可指评价艺术、书籍或电影的人；but 对照褒贬意见。','对小说艺术效果作具体评论，是评论家义 s1。')],mistakes:[M('The film critic delivered parcels to every cinema but never watched or evaluated a film.','The film critic watched and evaluated the movie, then published an assessment.','只送包裹而不评价作品的人是 courier，不是 critic。','confusable')],quiz:[Q('critic',1,1,'A film critic usually?',['evaluates and writes about films','acts in every film reviewed','delivers packages to cinemas'],'evaluates and writes about films','A critic judges art, books, or films.'),Q('critic',2,2,'A critic of the new policy is someone who?',['expresses disapproval or objections','delivers the official notice','is automatically the policy’s author'],'expresses disapproval or objections','Critic can broadly mean a person who criticizes.'),Q('critic',3,1,'Which person is most clearly a critic?',['a reviewer comparing a play’s acting and direction','an usher pointing visitors to their seats','a clerk stamping entry tickets only'],'a reviewer comparing a play’s acting and direction','The reviewer judges artistic quality.'),Q('critic',4,1,'Which sentence uses critic in the arts sense?',['The critic compared the novel’s pacing with its vivid dialogue.','The critic was a small bay between cliffs.','The critic lowered its body under the bench.'],'The critic compared the novel’s pacing with its vivid dialogue.','The person evaluates a work of literature.') ]});

  D('critical',{etymology:E('Critical came through French critique/Latin criticus from Greek kritikos, “able to judge.” It developed three related but distinct senses: judging faults, being essential, and describing a dangerous condition.','critical'),contexts:[C('critical.s2','工程安全','A working pressure sensor is critical to the reactor’s safety system; without it, operators could miss a dangerous rise before the automatic shutdown begins.','正常工作的压力传感器对反应堆安全系统至关重要；没有它，操作员可能会在自动停机启动前漏掉危险的压力上升。','A working pressure sensor is critical to the reactor’s safety system / without it / operators could miss a dangerous rise / before the automatic shutdown begins.','be critical to 表示对……至关重要；without it 说明缺少该部件的后果。','缺少传感器会削弱安全系统关键功能，符合重要、不可或缺义 s2。')],mistakes:[M('The sensor was critical to the safety system, but removing it had no effect on safety or the system’s operation.','The sensor was critical to the safety system because removing it would prevent detection of dangerous pressure.','若移除完全不影响功能，就不能说该部件对系统至关重要。')],quiz:[Q('critical',1,2,'A component critical to an aircraft is?',['essential to its operation or safety','merely decorative and unnecessary','a person who reviews films'],'essential to its operation or safety','The important sense means extremely necessary.'),Q('critical',2,1,'A critical review of a book is one that?',['examines and points out strengths or faults','guarantees every reader will like it','describes a patient’s vital signs'],'examines and points out strengths or faults','Critical can mean judging something carefully, often noting faults.'),Q('critical',3,3,'A patient in critical condition is?',['dangerously ill or injured','simply receiving a book review','essential to an engine'],'dangerously ill or injured','The medical sense means dangerously serious.'),Q('critical',4,2,'“Water is critical to the crop” means?',['water is essential for the crop','water is criticizing the crop','the crop is dangerously ill'],'water is essential for the crop','Critical to means necessary or extremely important.') ]});

  D('critically',{etymology:E('Critically is critical plus -ly; critical came through Greek kritikos, “able to judge.” The adverb may describe careful evaluation or something of extreme importance or dangerous seriousness.','critically'),contexts:[C('critically.s1','科研评估','The panel read the study critically, checking whether the sample was large enough and whether the authors had considered other explanations for the result.','评审组审慎地阅读这项研究，检查样本量是否足够，以及作者是否考虑过其他解释。','The panel read the study critically / checking whether the sample was large enough / and whether the authors had considered other explanations / for the result.','read critically 表示带着判断审视；whether 引导核查内容。','评审人员检查样本和替代解释，体现审慎批判地评估 s1。')],mistakes:[M('The panel read the study critically by accepting every claim without checking methods, evidence, or alternative explanations.','The panel read the study uncritically by accepting every claim without checking its evidence.','毫无审查地接受所有观点是 uncritically，不是 critically。','confusable')],quiz:[Q('critically',1,1,'To read a report critically is to?',['evaluate its claims and evidence carefully','believe every sentence automatically','read it only during an emergency'],'evaluate its claims and evidence carefully','Critically can mean with careful judgment and attention to faults or evidence.'),Q('critically',2,2,'A patient is critically ill. The patient is?',['dangerously ill','reviewing an essay','essential to a machine'],'dangerously ill','Critically can mean in a dangerously serious condition.'),Q('critically',3,1,'A team thinks critically about a proposal by?',['testing assumptions and evidence','repeating its title','praising it without reading it'],'testing assumptions and evidence','Critical thought assesses reasoning rather than accepting it blindly.'),Q('critically',4,2,'“The patient was critically injured” means?',['the injuries were dangerously severe','the patient wrote an arts review','the patient was a critical part of a machine'],'the injuries were dangerously severe','The adverb describes extreme, dangerous seriousness.') ]});

  D('criticism',{etymology:E('Criticism came through French critique from Greek kritikos, “able to judge,” with the noun suffix -ism; it can mean disapproval or written evaluation of art and literature.','criticism'),contexts:[C('criticism.s2','文学评论','Her criticism of the collection compared its recurring images, pacing, and point of view, and the review noted that the final story was more ambitious than the earlier ones.','她对这本文集的评论比较了反复出现的意象、节奏和叙事视角；书评指出最后一篇小说比前几篇更有野心。','Her criticism of the collection compared its recurring images, pacing, and point of view / and the review noted / that the final story was more ambitious / than the earlier ones.','criticism of a collection 可指对文学作品的评论文章；that 从句补充书评判断。','分析文学作品形式与内容的书面评价，符合文评义 s2。')],mistakes:[M('Her criticism of the novel was a list of postal addresses with no judgment, comments, or discussion of the book.','Her criticism of the novel discussed its style, ideas, and weaknesses.','与作品无关的地址清单不是对作品的批评或评论。')],quiz:[Q('criticism',1,1,'Criticism of a plan may be?',['remarks identifying what is wrong with it','a guarantee that nobody objects','a type of sea current'],'remarks identifying what is wrong with it','Criticism can mean saying what is wrong or expressing disapproval.'),Q('criticism',2,2,'A book review is a form of?',['literary criticism','countercurrent','courtship'],'literary criticism','The second sense is writing that evaluates books or art.'),Q('criticism',3,1,'A proposal faces criticism when people?',['point out its faults or objections','approve every detail silently','deliver it by courier'],'point out its faults or objections','Criticism can be expressed objections or fault-finding.'),Q('criticism',4,2,'A university course in film criticism studies?',['how films are interpreted and evaluated','how to build a courthouse','how to breed cattle'],'how films are interpreted and evaluated','Criticism also names the analysis and evaluation of artistic works.') ]});

  D('crook',{etymology:E('Crook came from Old Norse krókr “hook or bend” through Middle English; it names a curved part or hooked staff and also, by figurative development, a dishonest person.','crook'),contexts:[C('crook.s1','犯罪调查','The investigator traced the payment to a crook who had used a fake charity account to divert donations from families seeking medical help.','调查人员追查到一名骗子；他利用假慈善账户，把原本帮助求医家庭的捐款转走。','The investigator traced the payment / to a crook / who had used a fake charity account / to divert donations from families seeking medical help.','crook 作名词指骗子；who 从句说明其欺骗手法。','伪造账户并骗走捐款，符合不诚实的人这一义项。')],mistakes:[M('The crook returned every stolen donation, confessed, and had never deceived or cheated anyone.','The crook diverted donations through a fake account and deceived the donors.','诚实归还且从未欺骗的人不符合 crook“骗子”义。')],quiz:[Q('crook',1,1,'In “the police arrested a crook,” crook means?',['a dishonest person','a careful critic','a farm building'],'a dishonest person','Crook can be an informal noun for a criminal or dishonest person.'),Q('crook',2,1,'A shepherd’s crook is?',['a staff with a hooked end','a straight ruler','a courtroom chair'],'a staff with a hooked end','The older concrete sense is a bent or hooked stick.'),Q('crook',3,2,'To crook a finger is to?',['bend it into a hook shape','deliver a letter with it','make it perfectly straight'],'bend it into a hook shape','The verb means to bend a finger or other object into a hook.'),Q('crook',4,1,'A dishonest dealer who steals clients’ money is a?',['crook','cove','crayfish'],'crook','The informal person sense refers to a cheat or criminal.') ]});

  D('cross-section',{etymology:E('Cross-section combines cross- (a cut across) and section, from Latin sectio “a cutting”; it names either the surface exposed by a transverse cut or a representative sample.','cross-section'),contexts:[C('cross-section.s2','社会调查','The survey recruited a cross-section of residents from every district, including renters, homeowners, students, and retirees rather than only business owners.','调查从每个区招募了具有代表性的居民样本，包括租户、房主、学生和退休者，而不是只调查企业主。','The survey recruited a cross-section of residents / from every district / including renters, homeowners, students, and retirees / rather than only business owners.','a cross-section of residents 指有代表性的抽样群体；including 列举其构成。','样本涵盖不同区域与身份群体，能代表更大居民总体，符合 s2。')],mistakes:[M('The survey called 200 business owners a cross-section of all residents, although it excluded every other group in the city.','The survey included residents from varied districts and backgrounds to create a cross-section of the city.','只从单一群体取样无法代表全体多样人群。')],quiz:[Q('cross-section',1,2,'A cross-section of a community is?',['a sample representing different parts of it','a single person chosen from one family only','a cut surface through a rock'],'a sample representing different parts of it','The figurative sense is a representative selection from a larger group.'),Q('cross-section',2,1,'A diagram of a pipe cut straight across shows its?',['cross-section','courtship','credibility'],'cross-section','The literal sense is the surface exposed by cutting across an object.'),Q('cross-section',3,2,'A poll needs a cross-section of voters. It should include?',['different relevant groups of voters','only one friend of the pollster','no one who lives in the area'],'different relevant groups of voters','A representative sample reflects varied parts of the whole.'),Q('cross-section',4,1,'Which image shows a cross-section of a tree trunk?',['the rings visible on the cut end','its leaves viewed from above','a list of nearby trees'],'the rings visible on the cut end','The cut end exposes the tree’s transverse section.') ]});

  D('crossbill',{etymology:E('Crossbill combines cross and bill; the finch is named for its unusual mandibles whose tips cross, an adaptation that helps it open conifer cones.','crossbill'),contexts:[C('crossbill.s1','鸟类观察','The birdwatcher recognized a crossbill by its crossed bill and watched it lever open a pine cone to reach the seeds inside.','观鸟者凭交叉的喙认出这是一只交喙鸟，并看着它用喙撬开松果取食里面的种子。','The birdwatcher recognized a crossbill / by its crossed bill / and watched it lever open a pine cone / to reach the seeds inside.','recognize A by B；crossbill 是喙尖交叉的雀类。','交叉的喙帮助鸟打开松果取籽，是辨认交喙鸟的特征。')],mistakes:[M('The bird was a crossbill, but its upper and lower bill tips were parallel and never crossed.','The bird was a crossbill, with bill tips that crossed and helped it open cones.','喙尖没有交叉就缺少 crossbill 名称所指的关键特征。')],quiz:[Q('crossbill',1,1,'A crossbill is a finch with?',['mandibles that cross at the tips','a flat bill for filtering mud','a hooked tail like a crook'],'mandibles that cross at the tips','Its crossed bill is the feature behind its name.'),Q('crossbill',2,1,'What does a crossbill use its bill to help open?',['conifer cones','courtroom doors','cowsheds'],'conifer cones','Crossbills use their bill shape to remove seeds from cones.'),Q('crossbill',3,1,'A bird with crossed bill tips is likely a?',['crossbill','coyote','crayfish'],'crossbill','The finch is named for its crossed mandibles.'),Q('crossbill',4,1,'Which habitat activity suits a crossbill?',['extracting seeds from pine cones','delivering legal papers','hiding in a courthouse'],'extracting seeds from pine cones','The bill adaptation helps it open conifer cones.') ]});

  D('crossbones',{etymology:E('Crossbones combines cross and bones and conventionally names two long bones crossed beneath a skull, a traditional warning emblem.','crossbones'),contexts:[C('crossbones.s1','危险标识','The laboratory placed a skull and crossbones label on the solvent cabinet, warning visitors that the chemicals inside were poisonous if swallowed.','实验室在溶剂柜上贴了骷髅交叉骨标志，提醒访客里面的化学品吞下后有毒。','The laboratory placed a skull and crossbones label / on the solvent cabinet / warning visitors / that the chemicals inside were poisonous if swallowed.','skull and crossbones 是固定警告图案名称；warning 分词说明标识作用。','骷髅下交叉的骨头作为毒物警告符号，符合 crossbones 义。')],mistakes:[M('The pirate flag displayed crossbones as two parallel sticks that never touched or crossed.','The pirate flag displayed crossbones as two bones crossed beneath a skull.','平行不相交的骨头不构成交叉骨图案。')],quiz:[Q('crossbones',1,1,'Crossbones are conventionally shown?',['crossed beneath a skull','as a single straight line above a flower','inside a courtroom transcript'],'crossed beneath a skull','The familiar emblem consists of two crossed bones, usually below a skull.'),Q('crossbones',2,1,'A skull and crossbones sign often warns of?',['poison or serious danger','a cosy room','a representative survey'],'poison or serious danger','The symbol is widely used as a danger warning.'),Q('crossbones',3,1,'The crossed-bone image on a flag is called?',['crossbones','cross-section','crosscurrent'],'crossbones','Crossbones names the crossed-bone design.'),Q('crossbones',4,1,'Which label might feature crossbones?',['a cabinet containing toxic chemicals','a list of local councillors','a cottonwood planting guide'],'a cabinet containing toxic chemicals','The emblem warns people about poisonous hazards.') ]});

  D('crossbreeding',{etymology:E('Crossbreeding is cross- plus breeding, the -ing form of breed; it names producing offspring by mating plants or animals from different breeds.','crossbreeding'),contexts:[C('crossbreeding.s1','农业育种','The farm used crossbreeding to combine a hardy local sheep breed with a line known for wool quality, then tracked the lambs’ health and fleece over several seasons.','农场通过杂交育种把耐寒的本地绵羊品种与羊毛品质出色的品系结合起来，并连续几个季节记录羔羊健康和羊毛情况。','The farm used crossbreeding / to combine a hardy local sheep breed / with a line known for wool quality / then tracked the lambs’ health and fleece.','crossbreeding 指不同品种交配产生后代；combine A with B 说明育种目标。','两个不同绵羊品种结合并观察后代性状，符合杂交育种义。')],mistakes:[M('The farm called mating two animals from the same unchanged breed crossbreeding even though no different breeds were crossed.','The farm used crossbreeding by mating animals from two different breeds.','同一品种内繁殖而没有跨品种交配，不符合 crossbreeding 的定义。')],quiz:[Q('crossbreeding',1,1,'Crossbreeding involves?',['mating animals or plants from different breeds','repeating the same line with no cross','crossing a street on foot'],'mating animals or plants from different breeds','Crossbreeding produces offspring from different breeds.'),Q('crossbreeding',2,1,'A farmer mates two plant varieties to combine their traits. This is?',['crossbreeding','courtship','cramming'],'crossbreeding','The varieties are being crossed to produce offspring.'),Q('crossbreeding',3,1,'A breeder wants hardiness from one breed and wool quality from another. The process is?',['crossbreeding','credentialism','crassness'],'crossbreeding','Mating different breeds can combine desired characteristics.'),Q('crossbreeding',4,1,'Which case is not crossbreeding?',['mating two animals from the same breed only','mating two distinct cattle breeds','crossing two plant varieties'],'mating two animals from the same breed only','The word requires a cross between different breeds or varieties.') ]});

  D('crosscut',{etymology:E('Crosscut combines cross- and cut. As a noun it is a cut across the grain or a path that cuts across; as a verb it means to cut across grain or traverse an area directly.','crosscut'),contexts:[C('crosscut.s2','伐木作业','The carpenter crosscut the board across its grain with a fine-toothed saw, keeping the cut square so the two pieces would fit the cabinet frame.','木匠用细齿锯横着木纹锯开木板，并让切口保持方正，好使两块木料能装进柜框。','The carpenter crosscut the board across its grain / with a fine-toothed saw / keeping the cut square / so the two pieces would fit the cabinet frame.','crosscut 作动词指横切；across its grain 明示锯切方向。','锯口穿过木纹而非顺纹，符合动词义 s2。')],mistakes:[M('The carpenter crosscut the board by sawing only along the grain from end to end.','The carpenter crosscut the board by sawing across its grain.','沿木纹纵切不是横切；crosscut 指切过木纹。')],quiz:[Q('crosscut',1,1,'A crosscut through wood goes?',['across the grain','only along the grain','around the outside without cutting'],'across the grain','As a noun, a crosscut is a cut made across the grain.'),Q('crosscut',2,2,'To crosscut a field is to?',['go straight across it','circle its edge repeatedly','hide beneath it'],'go straight across it','As a verb, crosscut can mean to cut across an area.'),Q('crosscut',3,1,'Which saw action makes a crosscut in a board?',['cutting across the wood fibres','cutting lengthwise with the grain','painting the surface'],'cutting across the wood fibres','The cut is transverse to the grain.'),Q('crosscut',4,2,'A trail crosscuts the meadow. The trail?',['cuts directly across the area','follows only the outer fence','is a court official'],'cuts directly across the area','The verb can describe a route crossing an area directly.') ]});

  D('crosswalk',{etymology:E('Crosswalk combines cross and walk and names a marked or signposted part of a road where pedestrians may cross; British English commonly uses pedestrian crossing.','crosswalk'),contexts:[C('crosswalk.s1','道路安全','The driver stopped before the crosswalk and waited until the last child had reached the pavement on the opposite side of the street.','司机在斑马线前停车，等最后一个孩子走到街道对面的路缘后才继续行驶。','The driver stopped before the crosswalk / and waited / until the last child had reached the pavement / on the opposite side of the street.','stop before a crosswalk；until 从句说明何时可安全继续。','行人从这里横穿街道，车辆须在标线前停下，符合人行横道义。')],mistakes:[M('The driver accelerated through the marked crosswalk while pedestrians were using it.','The driver stopped at the marked crosswalk and let the pedestrians cross.','人行横道是供行人过街的路段，不应在行人通行时加速驶过。')],quiz:[Q('crosswalk',1,1,'A crosswalk is part of a road marked for?',['pedestrians to cross','cattle to sleep','court hearings'],'pedestrians to cross','A crosswalk is a marked or signed pedestrian crossing.'),Q('crosswalk',2,1,'A driver should normally do what when a pedestrian is in the crosswalk?',['stop and allow the person to cross','sound the horn and speed up','park on the person’s path'],'stop and allow the person to cross','The crossing is designated for pedestrians.'),Q('crosswalk',3,1,'Which place is also called a crosswalk?',['a marked pedestrian crossing','a narrow glacier crack','a courtroom aisle'],'a marked pedestrian crossing','The compound names the portion of road where people cross.'),Q('crosswalk',4,1,'The crosswalk connects the two?',['sides of a street for pedestrians','ends of a courtroom argument','banks of an ocean'],'sides of a street for pedestrians','It marks a safe route across the roadway.') ]});

  D('crossword',{etymology:E('Crossword combines cross and word and was formed from the puzzle’s intersecting horizontal and vertical word entries; the first modern crossword appeared in a 1913 newspaper.','crossword'),contexts:[C('crossword.s1','益智游戏','She completed the crossword on the train by solving the short crossing entries first, then using those letters to work out the longer answers.','她在火车上填完了纵横字谜，先解出较短的交叉词，再利用已有字母推断较长答案。','She completed the crossword on the train / by solving the short crossing entries first / then using those letters / to work out the longer answers.','crossword 是纵横填字游戏；by + -ing 表示解题方式。','方格中横竖相交的词条由线索填写，符合该游戏义。')],mistakes:[M('The crossword was completed by painting every square black, leaving no entries or clues to solve.','The crossword was completed by filling the white squares with words that fit the clues.','把所有格子涂黑而不填写线索答案，不是完成纵横填字游戏。')],quiz:[Q('crossword',1,1,'A crossword is a puzzle solved by?',['filling a grid with words from clues','matching livestock with breeds','identifying a mountain cat'],'filling a grid with words from clues','The puzzle uses a pattern of squares and clues for intersecting words.'),Q('crossword',2,1,'In a crossword, an answer may share letters with?',['words running in the other direction','a river current only','a legal credential'],'words running in the other direction','Crossing horizontal and vertical entries constrain each other.'),Q('crossword',3,1,'Which item would appear in a crossword?',['numbered clues and a grid of squares','a cowshed and a herd','a passport checkpoint'],'numbered clues and a grid of squares','Those are standard puzzle components.'),Q('crossword',4,1,'She solved a crossword clue and wrote the answer in the grid. She was?',['completing a word puzzle','filing a lawsuit','crossbreeding plants'],'completing a word puzzle','A crossword is a word puzzle filled from clues.') ]});

  D('crucible',{etymology:E('Crucible came through French creuset from medieval Latin crucibulum, a melting pot; its figurative sense of a severe test developed from the intense heat used in such a vessel.','crucible'),contexts:[C('crucible.s2','社会变革','The flood became a crucible for the volunteer group: weeks of exhausting rescues tested its trust, forced clearer leadership, and changed how members prepared for future disasters.','洪水成了志愿团体的严峻考验：数周艰苦救援检验了成员间的信任，促使领导方式更清晰，也改变了大家为未来灾害所做的准备。','The flood became a crucible for the volunteer group / weeks of exhausting rescues tested its trust / forced clearer leadership / and changed how members prepared for future disasters.','become a crucible for 表示成为严峻考验；冒号后解释事件带来的改变。','艰难处境检验并改变了团体，符合比喻义 s2。')],mistakes:[M('The crisis was a crucible for the team, but it tested nothing, changed no decisions, and caused no pressure.','The crisis was a crucible for the team because it tested their unity and changed how they worked.','没有压力、考验或变化的处境不符合 crucible 的严峻考验义。')],quiz:[Q('crucible',1,1,'A crucible in a laboratory is a vessel used to?',['melt materials at high temperatures','carry letters to an office','house farm animals'],'melt materials at high temperatures','The literal crucible is heat-resistant and holds substances while they melt.'),Q('crucible',2,2,'A difficult year becomes a crucible for a team when it?',['severely tests and transforms the team','provides a quiet holiday','marks the team’s mailing address'],'severely tests and transforms the team','The figurative sense is a situation of severe trial and change.'),Q('crucible',3,1,'Which object is a literal crucible?',['a heat-resistant pot for melting metal','a pedestrian crossing','a word puzzle'],'a heat-resistant pot for melting metal','A crucible withstands heat used to melt substances.'),Q('crucible',4,2,'The crisis was a crucible for the community. It?',['tested people severely and helped change them','was a piece of laboratory equipment','was an ordinary day with no challenge'],'tested people severely and helped change them','The metaphor emphasizes a severe formative trial.') ]});

  D('crucify',{etymology:E('Crucify came through Old French crucifier from Latin crucifigere, “fix to a cross,” from crux “cross” and figere “fasten.” Its figurative sense means to condemn or criticize harshly in public.','crucify'),contexts:[C('crucify.s2','媒体评论','After the coach admitted the late substitution was a mistake, commentators crucified him online, repeating the error for days and ignoring the injuries that had limited his options.','教练承认换人太晚是个错误后，评论员在网上严厉抨击他，连续数日反复提起此事，却忽视了限制选择的伤病情况。','After the coach admitted the late substitution was a mistake / commentators crucified him online / repeating the error for days / and ignoring the injuries that had limited his options.','crucify 作比喻动词表示公开严厉批评；online 指批评发生的场所。','评论者在公众场合猛烈指责某人，符合比喻义 s2。')],mistakes:[M('The commentators crucified the coach by praising every decision publicly and refusing to mention any criticism.','The commentators crucified the coach by attacking his decision harshly in public.','公开称赞而毫无指责不是比喻义 crucify，后者指严厉公开批评。')],quiz:[Q('crucify',1,1,'In its literal sense, to crucify someone is to?',['put them to death on a cross','review their book','make them a legal adviser'],'put them to death on a cross','The original verb refers to execution by nailing or binding to a cross.'),Q('crucify',2,2,'A public figure is crucified in the press when?',['the press condemns them very harshly','they are praised gently','they are appointed to a council'],'the press condemns them very harshly','The figurative sense is severe public criticism.'),Q('crucify',3,2,'A reviewer crucified the film’s director. The reviewer?',['attacked the director harshly in public','carried the director’s parcel','built a crosswalk'],'attacked the director harshly in public','The figurative verb means to criticize someone severely.'),Q('crucify',4,1,'Which meaning is literal?',['execute by nailing or binding to a cross','criticize a policy in a newspaper','cross a meadow directly'],'execute by nailing or binding to a cross','The literal sense concerns death on a cross.') ]});

  D('crudely',{etymology:E('Crudely is crude plus -ly; crude came through French from Latin crudus “raw, rough, or unworked.” The adverb describes approximate or unskilled work.','crudely'),contexts:[C('crudely.s1','模型制作','The first map was crudely drawn in pencil, with only the main river and three villages marked, but it was accurate enough to guide the rescue team.','第一张地图用铅笔粗略绘成，只标出了主河道和三个村庄，但其准确度足以引导救援队。','The first map was crudely drawn in pencil / with only the main river and three villages marked / but it was accurate enough / to guide the rescue team.','crudely 修饰 drawn，表示制作粗略、不精细；but 转折说明虽简略仍有用。','地图细节少、画工粗糙但大致可用，符合粗略地义。')],mistakes:[M('The diagram was crudely rendered with exact measurements, polished shading, and carefully finished details throughout.','The diagram was crudely rendered with a few rough lines and approximate proportions.','精细、准确、润饰完善不属于 crudely 所指的粗糙或粗略方式。')],quiz:[Q('crudely',1,1,'A crudely drawn map is?',['rough and lacking fine detail','perfectly polished and exact','a person who judges films'],'rough and lacking fine detail','Crudely means in an unfinished, approximate, or unskilled way.'),Q('crudely',2,1,'A machine crudely made from spare parts is likely?',['roughly assembled','professionally polished in every detail','a small bay'],'roughly assembled','The adverb describes the rough manner of construction.'),Q('crudely',3,1,'Which sentence uses crudely naturally?',['The shelter was crudely built from scrap boards.','She crudely measured exactly to the nearest micron.','The crudely was a councillor.'],'The shelter was crudely built from scrap boards.','Scrap-board construction can be rough and unrefined.'),Q('crudely',4,1,'“The device was crudely fashioned” means it was?',['made in a rough, unskilled way','made with exquisite precision','criticized in a review'],'made in a rough, unskilled way','Crudely fashioned contrasts with carefully finished workmanship.') ]});

  D('crumb',{etymology:E('Crumb came from Old English cruma “small fragment,” related to Germanic words for a crumb; as a verb it means breaking food into crumbs or coating it with them.','crumb'),contexts:[C('crumb.s2','烹饪','The cook crumbed the stale bread into a bowl, mixed the pieces with herbs, and pressed the mixture onto the fish before baking it.','厨师把不新鲜的面包捏碎放进碗里，与香草混合后压在鱼肉上再烘烤。','The cook crumbed the stale bread into a bowl / mixed the pieces with herbs / and pressed the mixture onto the fish / before baking it.','crumb 作动词表示捏碎或裹上面包屑；并列动词展现烹饪过程。','把面包弄成碎屑并用于裹鱼，符合动词义 s2。')],mistakes:[M('The cook crumbed the fish by leaving the bread as one whole unbroken loaf and adding no crumbs.','The cook crumbed the bread into small pieces and used them to coat the fish.','整块面包未破碎，也未裹屑，不符合 crumb 作动词的操作。')],quiz:[Q('crumb',1,1,'A crumb is?',['a very small piece of bread or cake','a large courtroom','a wild canid'],'a very small piece of bread or cake','The common noun means a tiny fragment of baked food.'),Q('crumb',2,2,'To crumb a piece of fish is to?',['cover it with small bread pieces','carry it to the courthouse','bend it into a hook'],'cover it with small bread pieces','The verb can mean coating food with crumbs.'),Q('crumb',3,1,'“Not a crumb was left” means?',['not even a tiny bit remained','the whole loaf was untouched','a river stopped flowing'],'not even a tiny bit remained','Crumb can also mean a very small amount.'),Q('crumb',4,1,'Where might you find a crumb?',['on a plate after eating bread','inside a crosswalk signal','in a courthouse jury box'],'on a plate after eating bread','Crumbs are small fragments of bread or similar food.') ]});

  D('crumple',{etymology:E('Crumple is a frequentative form related to crump, “bend or curl,” with the verb sense of pressing something into folds; it can also describe a person collapsing suddenly.','crumple'),contexts:[C('crumple.s1','文件整理','Rather than discard the draft, he flattened the crumpled page under a heavy book and rewrote the two paragraphs whose ink had blurred.','他没有扔掉草稿，而是用一本厚书压平皱巴巴的纸页，并重写墨迹模糊的两段。','Rather than discard the draft / he flattened the crumpled page under a heavy book / and rewrote the two paragraphs / whose ink had blurred.','crumpled 作形容词描述被压出许多褶皱的纸；whose 从句说明需要重写的段落。','纸被揉压后满是褶皱，符合使物体起皱义 s1。')],mistakes:[M('She crumpled the sheet by smoothing every wrinkle until it lay perfectly flat and uncreased.','She crumpled the sheet by squeezing it into a mass of folds.','把皱褶完全抚平是 uncrumple/flatten，与 crumple 的动作相反。')],quiz:[Q('crumple',1,1,'To crumple a note is to?',['press it into many folds','write it in neat straight lines','deliver it quickly'],'press it into many folds','Crumple means to press something so that it becomes wrinkled.'),Q('crumple',2,2,'After the runner collapses from exhaustion, she crumples to the ground. Here crumple means?',['lose strength and fall suddenly','fold a sheet of paper','stand up confidently'],'lose strength and fall suddenly','The verb can describe a person falling or failing abruptly.'),Q('crumple',3,1,'Which object has been crumpled?',['a ball of paper covered in wrinkles','a smooth sheet held flat','a newly printed flat poster'],'a ball of paper covered in wrinkles','The many folds show that the paper was crumpled.'),Q('crumple',4,2,'The old chair crumpled under his weight. It?',['gave way or collapsed suddenly','was folded neatly into a box','delivered the letter'],'gave way or collapsed suddenly','Crumple can describe something collapsing under pressure.') ]});

  D('crusade',{etymology:E('Crusade came through French croisade from Spanish cruzada and medieval Latin cruciata, ultimately from Latin crux “cross”; it names the medieval wars and later a determined reform campaign.','crusade'),contexts:[C('crusade.s1','公共倡议','For a decade, the nurse led a crusade for safer drinking water, collecting test results, organizing public meetings, and pressing officials to replace corroded pipes.','十年来，这名护士持续推动安全饮用水改革，收集检测结果、组织公众会议，并敦促官员更换腐蚀的管道。','For a decade / the nurse led a crusade for safer drinking water / collecting test results / organizing public meetings / and pressing officials to replace corroded pipes.','lead a crusade for 表示长期坚定地推动某项事业；并列动词说明倡议行动。','长期、有决心地推动纠正她认为不当的问题，符合改革运动义 s1。')],mistakes:[M('The nurse’s crusade lasted one minute, involved no effort, and aimed to preserve the unsafe water system unchanged.','The nurse’s crusade involved years of determined work to improve the water system.','短暂且维护原状的行为不符合长期、坚定推动改革的 crusade。')],quiz:[Q('crusade',1,1,'A crusade for clean water is?',['a long, determined campaign for change','a single casual remark','a court room'],'a long, determined campaign for change','The modern sense is a sustained effort to correct a perceived wrong.'),Q('crusade',2,2,'The Crusades were historically?',['medieval wars fought by European Christians for the Holy Land','a modern series of election debates','a type of crossing road'],'medieval wars fought by European Christians for the Holy Land','The capitalized plural names the medieval religious wars.'),Q('crusade',3,1,'A community crusade against fraud would involve?',['persistent organized efforts to stop fraud','quietly accepting every fraudulent act','buying a new crossword'],'persistent organized efforts to stop fraud','A crusade is determined and sustained advocacy or action.'),Q('crusade',4,1,'Which person is leading a crusade?',['an organizer campaigning for years to reform unsafe housing','a visitor attending one meeting without acting','a courier carrying a one-time letter'],'an organizer campaigning for years to reform unsafe housing','Long-term determined efforts to change a problem fit the figurative sense.') ]});

  D('crushing',{etymology:E('Crushing is crush plus -ing; crush came through Old French from Latin cruscire, “break into pieces.” As an adjective it often means overwhelmingly severe or defeating.','crushing'),contexts:[C('crushing.s1','竞技比赛','The visitors suffered a crushing defeat, conceding four goals before halftime and failing to create a single clear chance throughout the match.','客队遭到压倒性惨败：半场前就丢了四球，整场比赛也没能创造一次明确得分机会。','The visitors suffered a crushing defeat / conceding four goals before halftime / and failing to create a single clear chance / throughout the match.','crushing 修饰 defeat，表示以巨大优势击败；冒号列出比分和表现。','比分差距巨大且一方毫无还手机会，是压倒性失败。')],mistakes:[M('The team celebrated a crushing victory despite losing by five goals and never threatening the opponent.','The team suffered a crushing defeat after losing by five goals.','大比分落败不是 crushing victory，而是 crushing defeat。','confusable')],quiz:[Q('crushing',1,1,'A crushing defeat is?',['an overwhelming loss','a narrow win after a close match','a friendly draw'],'an overwhelming loss','Crushing describes a defeat so decisive it overwhelms the loser.'),Q('crushing',2,1,'Crushing pressure on a budget is?',['extremely severe pressure','a tiny harmless charge','a review of the budget'],'extremely severe pressure','The adjective can mean overwhelmingly burdensome.'),Q('crushing',3,1,'Which score suggests a crushing defeat?',['6–0 after one team dominated throughout','1–0 after a close, balanced match','0–0 with equal chances'],'6–0 after one team dominated throughout','The large margin and dominance make the loss overwhelming.'),Q('crushing',4,1,'The news brought crushing disappointment. The disappointment was?',['overwhelmingly severe','mild and quickly forgotten','about a physical crosscut'],'overwhelmingly severe','Crushing figuratively means intensely painful or overwhelming.') ]});

  D('crustacean',{etymology:E('Crustacean derives from New Latin Crustacea, the animal group named from Latin crusta “hard shell,” with the adjective suffix -an. It can be a noun for an animal or adjective for the group.','crustacean'),contexts:[C('crustacean.s1','海洋生物','The marine biologist classified the shrimp as a crustacean because it had a hard outer shell, jointed limbs, and a segmented body.','海洋生物学家把这只虾归为甲壳动物，因为它有坚硬外壳、关节肢和分节的身体。','The marine biologist classified the shrimp as a crustacean / because it had a hard outer shell / jointed limbs / and a segmented body.','classify A as a crustacean；because 引出分类依据。','虾具有甲壳动物的硬壳与分节肢体，符合名词义。')],mistakes:[M('The biologist classified the shrimp as a crustacean even though it was a feathered mammal with no shell or jointed limbs.','The biologist classified the shrimp as a crustacean because it had a hard shell and jointed limbs.','有羽毛、无壳的哺乳动物描述不符合 crustacean 类群。')],quiz:[Q('crustacean',1,1,'A crab, lobster, or shrimp is a?',['crustacean','coyote','crossbill'],'crustacean','These animals belong to the hard-shelled crustacean group.'),Q('crustacean',2,2,'“Crustacean limbs” means limbs?',['belonging to or characteristic of crustaceans','used only in a courthouse','made of cottonwood'],'belonging to or characteristic of crustaceans','The adjective describes something relating to the crustacean group.'),Q('crustacean',3,1,'A hard outer shell and jointed limbs point to a?',['crustacean','songbird','flowering plant'],'crustacean','Those are characteristics of many crustaceans.'),Q('crustacean',4,1,'Which animal is most clearly a crustacean?',['a freshwater crayfish','a mountain lion','a poplar tree'],'a freshwater crayfish','Crayfish are shell-bearing members of the crustacean group.') ]});

  D('crustal',{etymology:E('Crustal is crust plus -al, meaning “of or relating to”; geological crust traces to Latin crusta “hard outer covering.” The adjective relates to Earth’s outer rocky shell.','crustal'),contexts:[C('crustal.s1','地球科学','Researchers mapped a crustal boundary beneath the peninsula by comparing seismic waves, which travelled at different speeds through the two types of rock.','研究人员通过比较地震波绘制了半岛下方的地壳边界，因为地震波在两类岩石中的传播速度不同。','Researchers mapped a crustal boundary beneath the peninsula / by comparing seismic waves / which travelled at different speeds / through the two types of rock.','crustal 修饰 boundary，指地壳相关边界；by comparing 说明研究方法。','地震波穿过不同岩层的数据用于识别地球外层岩石结构。')],mistakes:[M('The report called a cloud layer crustal because it formed in the atmosphere far above the solid Earth.','The report called a boundary between the outer rock layers crustal.','大气云层不属于地球的岩石外壳，不能称为 crustal。')],quiz:[Q('crustal',1,1,'Crustal refers to Earth’s?',['outer rocky shell','upper atmosphere only','ocean currents'],'outer rocky shell','Crustal means relating to the Earth’s crust.'),Q('crustal',2,1,'A crustal earthquake occurs in or is related to?',['the Earth’s crust','a courthouse','a bird’s bill'],'the Earth’s crust','The adjective identifies a connection with the outer rocky layer.'),Q('crustal',3,1,'Which phrase is natural in geology?',['crustal movement beneath the continent','crustal counseling for students','crustal parcel delivery'],'crustal movement beneath the continent','The movement of Earth’s crust is geological.'),Q('crustal',4,1,'The suffix -al in crustal contributes the meaning?',['relating to','someone who does','a past action'],'relating to','-al forms an adjective meaning pertaining to the noun.') ]});

  D('cryptic',{etymology:E('Cryptic came through Latin crypticus from Greek kryptikos, “hidden,” related to kryptein “hide”; it describes concealed, puzzling meanings or secret things.','cryptic'),contexts:[C('cryptic.s1','谜题线索','The crossword clue was cryptic: “A silent beginning surrounds a king” gave solvers no direct definition, only wordplay that had to be unpacked.','这条纵横字谜线索晦涩难懂：“无声的开头包围着一位国王”没有直接给出定义，只提供了需要拆解的文字游戏。','The crossword clue was cryptic / “A silent beginning surrounds a king” / gave solvers no direct definition / only wordplay that had to be unpacked.','cryptic 修饰 clue；冒号给出例子，only 对照直接释义与隐晦文字游戏。','线索隐藏真实答案，需要解读文字游戏才能理解，符合隐晦难懂义 s1。')],mistakes:[M('The instructions were cryptic because they stated every step in plain, complete language that no reader could misunderstand.','The instructions were clear because they stated every step in plain, complete language.','明白无误的指令不是 cryptic；该词强调隐藏且难懂的意思。')],quiz:[Q('cryptic',1,1,'A cryptic message is?',['hard to understand because its meaning is hidden','clear and direct in every detail','a kind of farm building'],'hard to understand because its meaning is hidden','Cryptic means having a concealed or puzzling meaning.'),Q('cryptic',2,2,'A cryptic smile may seem?',['secretive and mysterious','loudly explanatory','dangerously ill'],'secretive and mysterious','Cryptic can suggest something mysterious rather than open.'),Q('cryptic',3,1,'Which note is cryptic?',['“Blue after the third gate” with no explanation','“Turn left at the next street”','a map with every symbol clearly labelled'],'“Blue after the third gate” with no explanation','The unexplained phrase hides what it means.'),Q('cryptic',4,1,'Choose the best opposite of cryptic.',['plain and explicit','puzzling','secretive'],'plain and explicit','Clear explicit language is the opposite of cryptic.') ]});

})(globalThis);
